       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"15a270f2-05d4-5af1-adbc-cd41d251e20b","document_type":"judgment","category":"judicial","subcategory":"general","title":"زوجية -طلب االنقياد لبيت الزوجية -طلب فسخ النكاح لسوء العشرة -بعث حكمن -قرار احلكمن التفريق با عوض للضرر - احلكم بفسخ النكاح .","document_number":"3460936","case_number":"33451538","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":"الدائرة األحوال الشخصية األولى يف1434/4/30ه ونص احلاجة","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/11","year":"1434","subject":"زوجية -طلب االنقياد لبيت الزوجية -طلب فسخ النكاح لسوء العشرة -بعث حكمن -قرار احلكمن التفريق با عوض للضرر - احلكم بفسخ النكاح .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3460936:‬تاريخه ‪1434/3/11 :‬هـ‬\n                   ‫رقم الدعوى ‪33451538:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34272414‬تاريخه‪1434/7/18 :‬هـ‬\n\n\n‫زوجيــة ‪ -‬طلــب االنقيــاد لبيــت الزوجيــة ‪ -‬طلــب فســخ النــكاح لســوء‬\n‫العشــرة ‪ -‬بعــث حكمــن ‪ -‬قــرار احلكمــن التفريــق بــا عــوض للضــرر ‪-‬‬\n                                                 ‫احلكــم بفســخ النــكاح ‪.‬‬\n\n\n\n\n                                                                  ‫‪ .1‬قــال اهلل تعالــى ‪َ ( :‬و ِإ ْن ِخ ْف ُتـ ْـم ِشـ َـق َ‬\n‫اق َب ْينِهِ َمــا فَ اب َْع ُثــوا َح َك ًمــا ِّمـ ْـن أَهْ ِلـ ِه‬\n‫ان‬‫ك َ‬       ‫الل َب ْي َن ُه َمــا ِإ َّن َّ َ‬\n         ‫الل َ‬                              ‫َو َح َك ًمــا ِّمـ ْـن أَهْ ل َِهــا ِإن ُي ِريـ َـدا ِإ ْص َل ًحــا ُي َو ِّفـ ِـق َّ ُ‬\n                                                                                                          ‫ِيمــا َخ ِبيـ ًـرا)‪.‬‬\n                                                                                                                             ‫َعل ً‬\n                                ‫‪ .2‬قال اهلل تعالى (والالتي تخافون نشوزهن فعظوهن)‬\n‫‪ .3‬قال اهلل تعالى(ومن آياته أن خلق لكم من أنفســكم أزواحا لتســكنوا‬\n                                                                        ‫إليهــا وجعــل بينكــم مودة ورحمة )‬\n                                   ‫‪ .4‬قال اهلل تعالى(ولهن مثل الذي عليهن باملعروف)‬\n                                                            ‫‪ .5‬قال اهلل تعالى (وعاشروهن باملعروف)‬\n                               ‫‪ .6‬قال اهلل تعالى (فإمساك مبعروف أوتسريح بإحسان)‬\n‫‪ .7‬قــول الرســول صلــى اهلل عليــه وســلم (ال ضــرر وال ضــرار) رواه مالــك‬\n                                                                                                                  ‫واحلاكم‪.‬‬\n‫‪ .8‬قــول الرســول صلــى اهلل عليــه وســلم (أميــا امــرأة ســألت زوجهــا‬\n                       ‫الطــاق مــن غيــر مــا بــأس فحــرام عليهــا رائحــة اجلنــة)‬\n\n\n\n                                                                                                                                        ‫‪148‬‬\n\f      ‫ادعــى زوج علــى زوجتــه يطالبهــا بالرجــوع إلــى بيــت الزوجيــة‪ ،‬صادقــت‬\n      ‫املدعــى عليهــا علــى النــكاح وعلــى خروجهــا مــن املنــزل ورفضــت العــودة‬\n      ‫لســوء عشــرة املدعــى وأهانتــه لهــا وأخــذة أموالهــا وذكــرت أنــه هــو‬\n      ‫الــذي طردهــا مــن البيــت ورفضــت الرجــوع وطلبــت فســخ النــكاح‪،‬‬\n      ‫طلبــت احملكمــة مــن املدعــى عليهــا البينــة علــى مــا ذكرتــه فقالــت ال‬\n      ‫بينــة لــي إال أوالدي مــن املدعــي ولــن يحضــروا إلــى احملكمــة‪ ،‬اطلعــت‬\n      ‫احملكمــة علــى عقــد النــكاح فوجدتــه مطابقــا ملــا ذكــر املدعــي‪،‬‬\n      ‫ولعــدم وجــود بينــه نصحتهــا احملكمــة بأنــه ال يجــوز لهــا ســؤال الطــاق‬\n      ‫مــن غيــر بــأس وتذكيرهــا بحرمــة النشــوز ومــا يترتــب علــى ذلــك مــن‬\n      ‫تفريــق األســرة فأصــرت علــى طلبهــا الفســخ‪ ،‬نصحــت احملكمــة بعــد‬\n      ‫ذلــك الــزوج املدعــي بتطليــق املدعــى عليهــا فرفــض‪ ،‬اســتنادا لقولــه‬\n      ‫تعالــى (وإن خفتهــم شــقاق بينهمــا فبعثــوا حكمــا مــن أهلــه وحكمــا‬\n      ‫مــن أهلها‪...‬اآليــة) أمــرت احملكمــة كل واحــد مــن الزوجــن باختيــار‬\n      ‫حكمــا مــن أهلــه حلــل النــزاع بينهمــا فقــرر الطرفــان حتكيــم هيئــة‬\n      ‫النظــر لــدى احملكمــة‪ ،‬فــورد اجلــواب بأنــه بعــد االجتمــاع بالزوجــن‬\n      ‫ونصحهمــا والنظــر يف حالهمــا يــروا التفريــق بينهمــا بــا عــوض‪ ،‬ولقــرار‬\n      ‫احلكمــن يف هيئــة النظــر والن قــرار احلكمــن ال يشــترط باعتبــاره‬\n      ‫رضــا الزوجــة أو الــزوج كمــا قــرره العلمــاء وألنــه ليــس المســاك الزوجــة‬\n      ‫مــع تضررهــا وعــدم رغبتهــا يف زوجهــا إمســاك مبعــروف ولقولــه صلــى‬\n      ‫اهلل عليــه وســلم (ال ضــرر وال ضــرار) ولطــول مــدة تعليــق املــرأة التــي‬\n      ‫تقــارب الســنة ولعــدم التآلــف بــن الزوجــن فــكان البــد مــن إزالــة‬\n\n‫‪149‬‬\n\f‫الضــرر فســخت احملكمــة نــكاح املدعــى عليهــا مــن املدعــي وأفهمــت‬\n‫املدعــى عليهــا أن عليهــا العــدة حســب حالهــا‪ ،‬اعتــرض املدعــى عليــه‬\n                               ‫صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )000‬القاضــي يف احملكمــة‬\n‫العامــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامة‪/‬املســاعد وتاريــخ ‪1433/07/07‬ه املقيــدة باحملكمــة وتاريــخ‬\n‫‪1433/7/7‬ه ـ ففــي يــوم األحد املوافق‪1433/09/10‬هـ وحضر حلضوره‬\n‫وقــرر املدعــي أن احلاضــرة هــي زوجتــه املدعــى عليهــا وادعــى األول قائــا‬\n‫إن املدعــى عليهــا زوجتــي مبوجــب العقــد املرفــق صورتــه الصــادر مــن‬\n‫مصــر وأجنبــت منهــا ولديــن وأربــع بنــات وقــد خرجــت مــن منزلــي بتاريــخ‬\n‫‪1433/6/30‬ه ـ بــدون ســبب أطلــب إلزامهــا بالرجــوع إلى منــزل الزوجية‬\n‫هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليهــا قالــت مــا ذكــره املدعــي‬\n‫يف دعــواه مــن عقــد النــكاح واإلجنــاب واخلــروج مــن منزلــه بالتاريــخ‬\n‫املذكــور كلــه صحيــح وســبب خروجــي مــن منزلــه رغــم مكوثــي معــه‬\n‫مــدة طويلــة هــو ســوء عشــرته وإهانتــه املتكــررة لــي إضافــة إلــى ضربــه‬\n‫لــي وســوء خلقــه وأخــذه ألموالــي وســبب خروجــي هــو طــرده لــي وإهانتــه‬\n‫حيــث قــال لــي لــو أن لكــي كرامــة فاخرجــي مــن املنــزل فخرجــت وأنــا‬\n‫قــد كرهــت العيــش معــه وأطلــب فســخ نكاحــي منــه هكــذا ذكــرت‬\n‫وبعــرض ذلــك علــى املدعــي قــال الصحيــح مــا ذكرتــه وبســؤال املدعــى‬\n‫عليهــا هــل لديــك بينــة علــى مــا ذكرتــي فأجابــت قائلــة ليــس لــدي بينــة‬\n‫علــى ذلــك ســوى أوالدي وهــم ال يســتطيعون احلضــور أمــام فضيلتكــم‬\n\n                                                                                    ‫‪150‬‬\n\f      ‫هكــذا أجابــت وباالطــاع علــى صــورة عقــد النــكاح وجدتــه مطابقــا‬\n      ‫ملــا ذكــره املدعــي واملهــر ‪ 301‬جنيــه احلــال منــه جنيــه واحــد واملؤخــر‬\n      ‫ثالثمائــة جنيــه بذمــة الــزوج ألقــرب األجلــن بعــد ذلــك ولعــدم وجــود بينــة‬\n      ‫لــدى املدعيــة جــرى نصحهــا اســتنادا إلــى قولــه تعالــى (والـ ــتي تخافــون‬\n      ‫نشــوزهن فعظوهــن) وتذكيرهــا بحرمــة النشــوز وطلــب الطــاق مــن‬\n      ‫غيــر ســبب يســتوجب ذلــك اســتنادا إلــى قولــه صلــى اهلل عليــه وســلم (أميا‬\n      ‫امــرأة ســألت زوجهــا الطــاق مــن غيــر مــا بــأس فحــرام عليهــا رائحــة‬\n      ‫اجلنــة) وتذكيرهــا باآلثــار املترتبــة علــى النشــوز والطــاق مــن تفــرق‬\n      ‫األســرة وخصوصــا مــع وجــود أوالد يحتاجــون إلــى الرعايــة وتكاتــف‬\n      ‫األســرة واجتماعهــا فأصــرت علــى طلبهــا بعــد ذلــك جــرى نصــح الــزوج‬\n      ‫لعلــه يطلقهــا ويرزقــه اهلل خيــرا منهــا أو يطلقهــا علــى عــوض أو يدفــع لهــا‬\n      ‫مــا يرضيهــا فقــال أنــا أرغــب يف زوجتــي ولــن أطلقهــا أو أخالعهــا وغيــر‬\n      ‫مســتعد بدفــع رضــوى لهــا ألننــي لــم أطردهــا أو آذيهــا هكــذا ذكــر بعد‬\n      ‫ذلــك واســتنادا لقولــه تعالــى (وإن خفتــم شــقاق بينهمــا فابعثــوا حكمــا‬\n      ‫مــن أهلــه وحكمــا مــن أهلهــا إن يريــدا إصالحــا يوفــق اهلل بينهمــا إن‬\n      ‫اهلل كان عليمــا خبيــرا ) أمــرت كل واحــد منهمــا أي الزوجــن باختيار‬\n      ‫حكــم ممــن يوثــق يف دينــه وأمانتــه وحكمتــه فقــاال جميعــا نرغــب يف‬\n      ‫حتكيــم هيئــة النظــر باحملكمــة لديكــم ونحــن نرضــى مبــا يقــرره‬\n      ‫احلكمــان هكــذا ذكــرا وحتــى الكتابــة لهيئــة النظــر وورود اإلجابــة‬\n      ‫جــرى رفــع اجللســة ويف يــوم الثالثــاء املوافــق‪1434/02/26‬ه حضــرت‬\n      ‫وباالطــاع علــى أوراق املعاملــة وردتنــا إفــادة مديــر مكتــب الصلــح‬\n      ‫باحملكمــة يف ‪1434/2/18‬ه ـ واملتضمــن مــا نصــه (بأنــه مت االجتمــاع‬\n      ‫بالطرفــن عــدة مــرات وجــرى مداولــة الصلــح بينهمــا والســعي يف تقريــب‬\n\n\n‫‪151‬‬\n\f‫وجهــات النظــر وإيجــاد احللــول املناســبة أمــا يف احلفــاظ علــى بيــت‬\n‫الزوجيــة والبقــاء علــى كيــان األســرة وبيــان مغبــة الشــقاق ومــا يترتــب‬\n‫عليــه مــن آثــار إال أن الزوجــة أصــرت علــى عــدم االنقيــاد حيــث ذكــرت‬\n‫أنــه يســيء معاشــرتها ويهينهــا ويضربهــا ويطلــب منهــا أمــور محرمــة‬\n‫وأنهــا تكرهــه وال تطيــق العيــش معــه فجــرى تذكيرهــا بــاهلل عــز وجــل‬\n‫وبقولــه صلــى اهلل عليــه وســلم (أميــا امــرأة طلبــت زوجهــا الطــاق مــن‬\n‫غيــر مــا بــأس فحــرام عليهــا رائحــة اجلنــة) وتذكيرهمــا باآلثــار املترتبــة‬\n‫علــى الطــاق خصوص ـ ًا أن بينهمــا أوالد وعشــرة طويلــة كمــا جــرى‬\n‫مناصحــة الــزوج بــأن يطلقهــا ويرزقهــا اهلل خيــر ًا منهــا حيــث إنــه ظهــر‬\n‫لنــا كرههــا الشــديد لهــا ولكنــه أصــر علــى طلــب انقيــاد زوجتــه وأنــه‬\n‫مســتعد بــأن يعاشــرها باملعــروف وأن ينفــق عليهــا وعلــى أوالده وقــد تبــن‬\n‫لنــا بغــض الزوجــة الشــديد لزوجهــا وانقيادهــا لزوجهــا وهــي علــى هــذه‬\n‫احلــال يفضــي إلــى النــزاع وال يخــدم احليــاة الزوجيــة ويتنافــى مــع قولــه‬\n‫تعالــى (ومــن آياتــه أن خلــق لكــم مــن أنفســكم أزواجــا لتســكنوا إليها‬\n‫وجعــل بينكــم مــودة ورحمــة ولقولــه صلــى اهلل عليــه وســلم ( ال ضــرر وال‬\n‫ضــرار) وحيــث إن بقــاء الزوجــة مــع زوجهــا علــى هــذا احلــال ضــرر محض‬\n‫لــذا فإننــا نــرى التفريــق بينهمــا بــدون عــوض وبــاهلل التوفيــق عليــه فقــد‬\n‫جــرى رفــع اجللســة ويف يــوم األربعــاء ‪1434/03/11‬ه ـ حضــرت املدعيــة‬\n‫ولــم يحضــر املدعــي وقالــت املدعــى عليهــا أنــا قــد كرهــت العيــش‬\n‫مــع هــذا الــزوج ومرفــق بــاألوراق معاملــة تتعلــق بطلــب فســخ النــكاح‬\n‫ومت ضمهــا بهــذه املعاملــة ألن الدعــوى أقيمــت أوال مــن الــزوج هكــذا‬\n‫ذكــرت وبنــاء علــى مــا تقــدم وملــا جــاء يف قــرار هيئــة النظــر املتضمــن‬\n‫التفريــق بينهمــا بــدون عــوض ومبــا أن قــرار احلكمــن ال يشــترط‬\n\n\n                                                                                      ‫‪152‬‬\n\f      ‫العتبــاره رضــا الــزوج والزوجــة جــاء يف أبحــاث هيئــة كبــار العلمــاء‬\n      ‫(ذهــب بعــض العلمــاء إلــى أن حكــم ولــي األمــر أو نائبــه يــراه مــن جمــع‬\n      ‫ـواء رضــي الــزوج بالطــاق أم‬   ‫أو تفريــق بعــوض أو بغيــر عــوض نافــذ سـ ً‬\n      ‫أبــى ورضيــت الزوجــة بدفــع العــوض أم كرهــت رعايــة ملصلحــة األســرة‬\n      ‫خاصــة ومصلحــة املجتمــع اإلســامي عامــة وروي عــن علــي رضــي اهلل‬\n      ‫عنــه أنــه أتــاه رجــل وامرأتــه مــع كل واحــد منهمــا فئــام مــن النــاس فقــال‬\n      ‫علــي مــا شــأن هذيــن قالــوا بينهمــا شــقاق قــال فابعثــوا حكمــا مــن أهلــه‬\n      ‫وحكمــا مــن أهلهــا إن يريــدا إصالحــا يوفــق اهلل بينهمــا فقــال علــي‬\n      ‫هــل تدريــان مــا عليكمــا؟ عليكمــا إن رأيتمــا أن جتمعــا إن جتمعــا‬\n      ‫وإن رأيتمــا أن تفرقــا أن تفرقــا فقالــت املــرأة رضيــت بكتــاب اهلل فقــال‬\n      ‫الرجــل أمــا الفرقــة فــا فقــال علــي كذبــت واهلل ال تنفلــت حتــى تقــر‬\n      ‫كمــا أقــرت (وجــاء يف أبحــاث هيئــة كبــار العلمــاء) والــذي صــح عــن‬\n      ‫ابــن عبــاس مــا قدمنــا مــن أنهمــا حكمــان ال شــاهدان فــإذا فرقــا بينهمــا‬\n      ‫وهــي املســألة الرابعــة تكــون الفرقــة كمــا قــال علماؤنــا لوقــوع اخللــل‬\n      ‫يف مقصــود النــكاح مــن األلفــة وحســن العشــرة فــإن قيــل إذا ظهــر‬\n      ‫الظلــم مــن الــزوج أو الزوجــة فظهــور الظلــم ال ينــايف النــكاح بــل يؤخــذ‬\n      ‫مــن الظالــم حــق املظلــوم ويبقــى العقــد قلنــا هــذا نظــر قاصــر يتصــور‬\n      ‫يف عقــود األمــوال فأمــا عقــود األبــدان فــا يتــم إال باالتفــاق والتآلــف‬\n      ‫وحســن التعاشــر فــإذا فقــد ذلــك لــم يكــن لبقــاء العقــد وجــه وكانــت‬\n      ‫املصلحــة يف الفرقــة وبــأي وجــه رأياهــا مــن املتاركــة أو أخــذ شــيء مــن‬\n      ‫الــزوج أو الزوجــة (وجــاء يف أبحــاث هيئــة كبــار العلمــاء (واتفقــوا علــى‬\n      ‫أن احلكمــن ينفــذ مــا رأيــاه يف الصلــح بينهمــا) ونظــرا لطــول الفراق بني‬\n      ‫الطرفــن ولقولــه تعالــى (فإمســاك مبعــروف أو تســريح بإحســان) وقولــه‬\n\n\n‫‪153‬‬\n\f‫تعالــى (وعاشــروهن باملعــروف) وليــس اإلمســاك مــع تضــرر املدعيــة‬\n‫وعــدم رغبتهــا يف املدعــى عليــه إمســاك ًا وال معاشــرة باملعــروف فيتعــن‬\n‫التســريح ونظــر ًا لكــون عقــد الزوجيــة ليــس عقــد بيــع وشــراء بــل هــو‬\n‫عقــد مماثلــة قــال تعالــى (ولهــن مثــل الــذي عليهــن باملعــروف) وأهــم هــذه‬\n‫احلقــوق وأخصهــا العشــرة اإلنســانية والتعامــل احلســن ولــذا إذا تضــررت‬\n‫الزوجــة مــن زوجهــا لســوء عشــرته وعــد رغبتــه فيهــا كان لهــا املطالبــة‬\n‫بالفســخ ألن اســتمرار احليــاة الزوجيــة مــع ســوء العشــرة فيهــا انتهــاك‬\n‫لكرامــة اإلنســان واعتــداء علــى احلكمــة مــن مشــروعية النــكاح وبنــاء‬\n‫على القاعدة الفقهية ال ضرر وال ضرار والضرر يزال ولقوله صلى اهلل‬\n‫عليــه وســلم (ال ضــرر وال ضــرار) أخرجــه مالــك يف املوطــأ واحلاكــم يف‬\n‫املســتدرك والبيهقــي والــدار قطنــي وابــن ماجــه وال شــك أن تــرك املدعية‬\n‫معلقــة هــذه املــدة التــي تقــارب الســنة مــع وجــود النــزاع بــن الزوجــن‬\n‫وعــدم التآلــف ضــرر علــى الزوجــة فــكان ال بــد مــن إزالــة هــذا الضــرر‬\n‫وجلميــع مــا تقــدم فقــد فســخت نــكاح (‪ )000000‬مــن زوجهــا (‪)00000‬‬\n‫وأفهمــت املدعيــة بــأن عليهــا العــدة الشــرعية لهــذا الفســخ علــى حســب‬\n‫حالهــا وأال تعــرض نفســها للخطــاب حلــن اكتســاب احلكــم القطعيــة‬\n‫وأفهمــت الــزوج بــأن زوجتــه قــد بانــت منــه بينونــة صغــرى وال حتــل لــه‬\n‫إال بعقــد جديــد بشــروطه وأركانــه وأفهمتهمــا باجتنــاب بعضهمــا حلــن‬\n‫اكتســاب احلكــم القطعيــة وبذلــك حكمــت وبعــرض احلكــم علــى‬\n‫الزوجــة قــررت القناعــة وســيتم إبــاغ الــزوج باحلكــم لتقريــر قناعتــه‬\n‫باحلكــم مــن عدمهــا مــع إفهامــه عنــد اعتراضــه بــأن لــه مــدة قدرهــا‬\n‫ثالثــون يومـ ًا اعتبــار ًا مــن تاريــخ اســتالمه للحكــم لتقــدمي اعتراضــه وإذا‬\n‫انتهــت املــدة ولــم يقــدم اعتراضــه فيهــا ســقط حقــه باســتئناف احلكــم‬\n\n\n                                                                                      ‫‪154‬‬\n\f      ‫واكتســب احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                   ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/3/11‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامة‪/‬املســاعد وتاريــخ ‪1433/07/07‬ه املقيــدة باحملكمــة وتاريــخ‬\n      ‫‪1433/7/7‬ه ففــي يــوم األربعــاء املوافــق ‪1434/05/15‬ه حيــث عــادت‬\n      ‫املعاملــة مــن محكمــة االســتئناف مبوجــب خطــاب رئيــس محكمــة‬\n      ‫االســتئناف يف ‪1434/5/6‬ه وبرفقهــا قــرار املالحظــة الصــادر مــن‬\n      ‫الدائــرة األحــوال الشــخصية األولــى يف‪1434/4/30‬ه ـ ونــص احلاجــة‬\n      ‫منــه (وبدراســة الصــك وصــوره ضبطــه والالئحــة االعتراضيــة وأوراق‬\n      ‫املعاملــة لوحــظ مايلــي ‪ -:‬ورد يف صــورة الضبــط أن املدعــى ســعودي‬\n      ‫اجلنســية بينمــا يف الصــك أنــه مصــري ووجــد ضمــن أوراق صورة لرخصة‬\n      ‫إقامــة املدعــى وأن جنســيته مصــري وأن الرقــم املــدون هــو رقــم إقامتــه‬\n      ‫فعلــى فضيلتــه تصحيــح ذلــك يف الضبــط وصورتــه ‪ .‬ثانيـ ًا ‪ :‬أفهــم فضيلته‬\n      ‫املدعــى عليهــا بــأن العــدة الشــرعية لهــذا الفســخ حســب حالهــا ولــم يبــن‬\n      ‫نــوع العــدة التــي تلزمهــا بعــد ســؤالها عــن حالهــا ثالث ـ ًا ‪ :‬ذكــر فضيلتــه‬\n      ‫بــأن ال تعــرض نفســها للخطــاب حلــن اكتســاب احلكــم القطعيــة ولــم‬\n      ‫يقيــد ذلــك بانتهــاء عدتهــا والبــد مــن ربطــه بــه فعلــى فضيلتــه مالحظــة‬\n      ‫مــا ذكــر وإكمــال مــا يلــزم) وعليــه أجيــب أصحــاب الفضيلــة حفظهــم‬\n      ‫اهلل بــأن املدعــي مصــري اجلنســية كمــا هــو موضــح يف الصــك وأوراق‬\n      ‫املعاملــة وكتــب ســعودي مــن قبــل الكاتــب ســهوا ويتعــذر التعديــل علــى‬\n      ‫الضبــط لوجــود تواقيــع أطــراف الدعــوى وأمــا مــا جــاء يف املالحظــة‬\n      ‫الثانيــة فــإن هــذا اإلفهــام فتــوى وهــو مــن املكمــات والــذي يترجــح لدي‬\n\n\n‫‪155‬‬\n\f‫أن عدتهــا أن تســتبرء بحيضــة واحــدة حيــث ذكــرت أنهــا حتيــض أثنــاء‬\n‫نظــر الدعــوى وأمــا مــا جــاء يف املالحظــة الثالثــة فإنــه بنــاء علــى قصــر‬\n‫العــدة وخصوص ـ ًا معطــول وقــت اإلجــراء مــن بعــث املعاملــة حملكمــة‬\n‫االســتئناف وروجهــا ممــا يتيقــن معــه انتهــاء عدتهــا غالب ـ ًا جــرى تــرك‬\n‫ذلــك اختصــارا ولكــن بنــاء علــى مــا ذكــره أصحــاب الفضيلــة فــإن‬\n‫اإلفهــام بعــد اكتســاب احلكــم القطعيــة وانتهــاء عدتهــا وبذلــك‬\n‫حكمــت وبذلــك مت إكمــال الــازم حيــال مالحظــة أصحــاب الفضيلــة‬\n‫وأمــرت بإحلــاق ذلــك علــى صــك احلكــم وســجله وبــاهلل التوفيــق وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                            ‫يف ‪1434/5/15‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )00000‬القاضــي يف احملكمــة‬\n‫العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة بالريــاض ورقــم وتاريــخ ‪1433/07/07‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331276998‬وتاريــخ ‪1433/07/07‬ه ففــي يــوم‬\n‫اخلميــس املوافق‪1434/09/10‬ه ـ حيــث عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف وبرفقهــا القــرار املــدون علــى ظهــر الصــك واملتضمــن مــا‬\n‫نصــه (تظهيــرات دائــرة األحــوال الشــخصية واالنهــاءات مبحكمــة‬\n‫االســتئناف بالريــاض احلمــد هلل وحــده وبعــد‪ :‬فقــد اطلعنــا علــى هــذا‬\n‫الصــك وتاريــخ ‪1434/03/11‬ه ـ الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة العامــة بالريــاض الشــيخ (‪ )0000‬وأصدرنــا القــرار وتاريــخ‬\n‫‪1434/07/18‬ه ـ املتضمــن بأنــه لــم يظهــر مــا يوجــب االعتــراض علــى‬\n‫احلكــم املــؤرخ ‪1434/03/11‬ه ـ واهلل املوفــق قاضــي اســتئناف (‪)000‬‬\n‫ختمــه وتوقيعــه قاضــي اســتئناف (‪ )000‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n\n\n                                                                                     ‫‪156‬‬\n\f      ‫(‪ )000‬ختمــه وتوقيعــه وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                         ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/9/10‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى بتمييــز‬\n      ‫قضايــا األحــوال الشــخصية واالنهــاءات مبحكمــة االســتئناف علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض ‪........‬‬\n      ‫وتاريــخ ‪1434/7/8‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ (‪ )0000‬املســجل وتاريــخ ‪1434/3/11‬ه ـ اخلــاص‬\n      ‫بدعــوى (‪ )00000‬مصــري اجلنســية ضــد (‪ )00000‬مصريــة اجلنســية‬\n      ‫بشــأن طلــب املدعــي إلــزام املدعــى عليهــا باالنقيــاد لبيــت الزوجيــة‪،‬‬\n      ‫وقــد تضمــن الصــك أن فضيلتــه فســخ نــكاح املدعيــة مــن املدعــى‬\n      ‫عليــه بــا عــوض ‪ ...‬إل ــخ وبــه حكــم ‪ .‬وحيــث ســبقت دراســة الصــك‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى‬\n      ‫مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك وصــورة ضبطــه بتاريــخ‬\n      ‫‪1434/5/15‬ه ـ بنــاء علــى قرارنــا وتاريــخ ‪1434/4/30‬ه ـ لــم يظهــر‬\n      ‫مــا يوجــب االعتــراض علــى احلكــم املــؤرخ ‪1434/3/11‬ه ـ مــع تنبيــه‬\n      ‫فضيلتــه إلــى أنــه لــم يطبــق املــادة ‪ 1/187‬مــن نظــام املرافعــات بشــأن‬\n      ‫قــرار الدائــرة يف ‪1434/6/13‬هــ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                                      ‫محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪157‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":148,"source_page_end":157,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"45a511f808f0a09856078ae9e598e8137308d9497d70f4eb27d4235f94cf1f7d","normalized_text_hash":"2de04253808dec2f8005bd9342ec5d0cfded45404891f2a925c55424e56be43a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p148-3460936"},{"id":"fec62b91-cdcf-5af6-827c-b7ce70d26ffb","document_type":"judgment","category":"judicial","subcategory":"general","title":"زوجية -طلب االنقياد لبيت الزوجية -األصل عدم العيب -عرض الصلح على الزوجة عن طريق قسم الصلح والذي اعتبر الزوجة ناشز ا -احلكم بإلزام املدعى عليها باالنقياد لبيت الزوجية.","document_number":"34194085","case_number":"33579594","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/21","year":"1434","subject":"زوجية -طلب االنقياد لبيت الزوجية -األصل عدم العيب -عرض الصلح على الزوجة عن طريق قسم الصلح والذي اعتبر الزوجة ناشز ا -احلكم بإلزام املدعى عليها باالنقياد لبيت الزوجية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34194085 :‬تاريخه ‪1434/4/21 :‬هـ‬\n                    ‫رقم الدعوى ‪33579594:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34346590‬تاريخه‪1434/11/21 :‬هـ‬\n\n\n ‫زوجيــة ‪ -‬طلــب االنقيــاد لبيــت الزوجيــة ‪ -‬األصــل عــدم العيــب ‪ -‬عــرض‬\n ‫الصلــح علــى الزوجــة عــن طريــق قســم الصلــح والــذي اعتبــر الزوجــة‬\n       ‫ناشــز ًا ‪ -‬احلكــم بإلــزام املدعــى عليهــا باالنقيــاد لبيــت الزوجيــة‪.‬‬\n\n\n\n\n ‫‪-1‬قــال يف الــروض املربــع (وإذا مت العقــد لــزم تســليم الزوجــة احلــرة‬\n                                ‫التي يوطأ مثلها يف بيت الزوج إن طلبه)‬\n ‫‪-2‬قــال صاحــب حاشــية الــروض (ألنــه بالعقــد يســتحق الــزوج تســليم‬\n                   ‫العــوض كمــا تســتحق تســليم الصــداق إن طلبتــه)‬\n                      ‫‪-3‬املادة رقم ‪ 55‬و‪ 176‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n ‫ادعــى زوج علــى زوجتــه يطالبهــا بالرجــوع إلــى بيــت الزوجيــة‪ ،‬صادقــت‬\n ‫املدعــى عليهــا علــى النــكاح وذكــرت أن املدعــي هــو الــذي طردهــا مــن‬\n ‫البيــت وأنــه ال مانــع لديهــا مــن الرجــوع إليــه واشــترطت أن يعتذر ألهلها‪،‬‬\n ‫حاولــت احملكمــة الصلــح بــن الطرفــن دون جــدوى ثــم لــم حتضــر‬\n ‫املدعــى عليهــا بعــد ذلــك إلــى احملكمــة فقــررت احملكمــة الســير يف‬\n ‫الدعــوى غيابيــا يف حــق املدعــى عليهــا بنــاء علــى املــادة (‪ )55‬مــن نظــام‬\n ‫املرافعــات الشــرعية‪ ،‬طلــب املدعــي احلكــم يف دعــواه‪ ،‬بنــاء عليــه وألن‬\n\n                                                                                     ‫‪158‬‬\n\f      ‫مــن الواجــب علــى الزوجــة االنقيــاد لزوجهــا وطاعتــه فيمــا ال معصيــة‬\n      ‫فيــه وبنــاء علــى أن املدعــي طلــب املدعــى عليهــا وألنــه لــم يثبــت يف الــزوج‬\n      ‫عيــب يكــون للزوجــة معــه طلــب الفســخ‪ ،‬وحيــث أقــرت املدعــى عليهــا‬\n      ‫أنــه ال مانــع لديهــا مــن العــودة للمدعــي إذا اعتــذر مــن أهلهــا‪ ،‬وبنــاء علــى‬\n      ‫املــادة ‪ 176/55‬مــن نظــام املرافعــات الشــرعية لــذا ألزمــت احملكمــة‬\n      ‫املدعــى عليهــا االنقيــاد لزوجهــا قنــع املدعــي وأفهــم بــأن هــذا احلكــم ال‬\n      ‫مينــع املدعــى عليهــا بالتقــدم إلــى احملكمــة بطلــب الفــراق ثــم جــرى رفــع‬\n      ‫هــذا احلكــم حملكمــة االســتئناف وطلبــت محكمــة االســتئناف مــن‬\n      ‫ناظــر القضيــة إفهــام املدعــى عليهــا بأنهــا إذا لــم تتمثــل للحكــم فإنهــا‬\n      ‫تعــد ناشــزا ويكــون ذلــك موجب ـ ًا لســقوط حقوقهــا الزوجيــة مــا دامــت‬\n         ‫مصــرة علــى عــدم االنقياد‪،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )000‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بجدة‪/‬املســاعد وتاريــخ ‪1433/09/18‬ه ـ املقيــدة‬\n      ‫باحملكمــة وتاريــخ ‪1433/09/18‬ه ـ ففــي يــوم الثالثــاء املوافــق‬\n      ‫‪1434/04/09‬ه ـ افتتحــت اجللســة الســاعة ‪ 01 : 30‬وفيهــا حضــر‬\n      ‫(‪ )00000‬ســعودي اجلنســية وادعى على احلاضرة معه (‪ )00000‬ســعودية‬\n      ‫اجلنســية واملعــرف بهــا شــقيقها (‪ )0000‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ )0000‬قائــا ‪ :‬إن املدعــى عليهــا زوجتــي ‪ ،‬عقــدت‬\n      ‫بهــا يف ‪1428/6/20‬ه ـ مبوجــب عقــد النــكاح الصــادر مــن احملكمــة‬\n      ‫اجلزئيــة للضمــان واألنكحــة وتاريــخ ‪1428/6/20‬هــ‪ ،‬علــى مهــر قــدره‬\n\n‫‪159‬‬\n\f‫عشــرون ألــف ريــال مــدون يف عقــد النــكاح ‪ ،‬وعشــرة آالف ريــال غيــر‬\n‫مــدون فيــه‪ ،‬إضافــة إلــى ذهــب بقيمــة قدرهــا تســعة آالف وثمامنائــة‬\n‫ريــال ‪ ،‬واملهــر مســلم بالكامــل ‪ ،‬ودخلــت بهــا يف ‪1428/10/27‬هــ‪،‬‬\n‫ورزقــت منهــا علــى فــراش الزوجيــة ولــدان همــا (‪ )0000‬مــن مواليــد‬\n‫‪1430/4/12‬ه ـ و (‪ )000‬مــن مواليــد ‪1432/9/15‬ه ـ ‪ ،‬وقــد وقــع‬\n‫خــاف بينــي وبــن املدعــى عليهــا يف شــهر صفر لعــام ‪1433‬هـ بخصوص‬\n‫زيارتهــا ألهلهــا ‪ ،‬وقــد خرجــت املدعــى عليهــا مــن بيتــي إثــر هــذا‬\n‫اخلــاف‪ ،‬ومــن أخذهــا هــو أبــي‪ ،‬وهــو مــن أوصلهــا لبيــت أهلهــا ‪ ،‬ومــن‬\n‫ذلــك الوقــت واملدعــى عليهــا لــم تعــد لبيتــي ‪ ،‬وقــد طلبتهــا للرجــوع لــه‬\n‫مرتــن كان أولهــا يف شــهر جمــادى الثانــي لعــام ‪1433‬ه ـ دون جــدوى ‪،‬‬\n‫أطلــب إلــزام املدعــى عليهــا باالنقيــاد لــي والرجــوع لبيــت الزوجيــة ‪ .‬هــذه‬\n‫دعــواي ثــم أبــرز أصــل عقــد النــكاح ‪ ،‬ومت إرفــاق نســخة منــه باملعاملــة‬\n‫‪ ،‬وبعــرض ذلــك علــى املدعــى عليهــا قالــت ‪ :‬إن مــا ذكــره املدعــي مــن‬\n‫العقــد والدخــول واإلجنــاب واخلــروج فصحيــح ‪ ،‬ووالــد املدعــي هــو مــن‬\n‫أقلنــي لبيــت أهلــي بطلــب مــن املدعــي ‪ ،‬فهــو مــن طردنــي ‪ ،‬وأمــا املهــر‬\n‫فالصحيــح أنــه ســلمني ثالثــن ألــف ريــال نقــدا ‪ ،‬وأعــاد لــه أبــي عشــرة‬\n‫آالف ريــال للمدعــي كمســاعدة لــه ‪ ،‬ثــم يعيدهــا ألبــي ‪ ،‬ولــم يفعــل ذلك‬\n‫بعــد‪ ،‬وأمــا الذهــب فــا أعــرف قيمتــه‪ ،‬وليــس مــن املهــر ‪ ،‬وقــد قدمــه‬\n‫كهديــة‪ ،‬وال مانــع لــدي مــن الرجــوع لــه‪ ،‬يف حــال اعتــذر مــن أهلــي ‪.‬‬\n‫ومبداولــة الصلــح بــن الطرفــن طلبــا اإلمهــال ملوعــد آخــر ‪ .‬ثــم رفعــت‬\n‫اجللســة لذلــك ‪ .‬ويف يــوم األحــد املوافق‪1434/04/14‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 02 : 15‬وفيهــا حضــر املدعــي ‪ ،‬ولــم حتضــر املدعــى عليهــا‬\n‫(‪ )0000‬وال مــن ميثلهــا ‪ ،‬وبنــاء علــى املــادة (‪ )55‬مــن نظــام املرافعــات‬\n\n\n                                                                                      ‫‪160‬‬\n\f      ‫الشــرعية فقــد قــررت الســير يف الدعــوى غيابيــا يف حــق املدعــى عليهــا‪،‬‬\n      ‫وقــرر املدعــي قائــا ‪ :‬أطلــب حتديــد موعــد أخــر للجلســة ‪ ،‬ثــم رفعــت‬\n      ‫اجللســة لذلــك ‪ .‬ويف يــوم األحــد املوافــق ‪1434/04/21‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 02 : 15‬وفيهــا حضــر املدعــي ‪ ،‬ولــم حتضــر املدعــى‬\n      ‫عليهــا وال مــن ميثلهــا ‪ ،‬وقــرر املدعــي قائــا‪ :‬أطلــب احلكــم يف الدعــوى‪.‬‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ‪ ،‬وبنــاء علــى أن مــن واجــب‬\n      ‫الزوجــة االنقيــاد لزوجهــا وطاعتــه فيمــا ال معصيــة فيــه ‪ ،‬وبنــاء علــى أن‬\n      ‫املدعــي طلــب املدعــى عليهــا لالنقيــاد لــه بصفتــه زوجــا لهــا‪ ،‬وبنــاء علــى‬\n      ‫أن الزوجــة إمــا أن تنقــاد للــزوج أو تفــادي نفســها منــه ‪ ،‬مــا لــم يثبــت أن‬\n      ‫بالــزوج عيبــا يكــون للزوجــة معــه طلــب الفســخ ‪ ،‬وبنــاء علــى أن األصــل‬\n      ‫عــدم العيــب ‪ ،‬وعلــى مدعــي خالفــه البينــة‪ ،‬وملــا قــرره أهــل العلــم مــن‬\n      ‫لــزوم تســليم الزوجــة لزوجهــا ‪ ،‬ومــن ذلــك مــا قــرره صاحــب لــروض‬\n      ‫املربــع ‪ ،‬ونصــه (وإذا مت العقــد لــزم تســليم الزوجــة احلــرة التــي يوطــأ‬\n      ‫مثلهــا ‪ ..‬يف بيــت الــزوج إن طلبــه) وذكــر صاحــب احلاشــية مــا نصــه (ألنــه‬\n      ‫بالعقــد يســتحق الــزوج تســليم العــوض ‪ ،‬كمــا تســتحق تســليم الصــداق‬\n      ‫إن طلبتــه) ‪ ،‬وبنــاء علــى أن املدعــى عليــه قــد أجابــت علــى دعــوى املدعــي‬\n      ‫بأنــه ال متانــع مــن العــودة للمدعــي يف حــال اعتــذر مــن أهلهــا ‪ ،‬وهــذه‬\n      ‫قرينــة علــى أن اخلــاف بــن الطرفــن فيمــا يتعلــق بعالقــة املدعــي بأهــل‬\n      ‫املدعــى عليهــا ‪،‬ولهــا املطالبــة بالفــراق مــا لــم تــرض بذلــك بعــد ثبوتــه ‪،‬‬\n      ‫وبنــاء علــى املــادة (‪ )55‬و (‪ )176‬مــن نظــام املرافعــات الشــرعية ‪ ،‬لذلــك‬\n      ‫كلــه ‪ ،‬فقــد ألزمــت املدعــى عليهــا باالنقيــاد لزوجهــا املدعــي‪ .‬وبــه‬\n      ‫حكمــت ‪ .‬وبــه قنــع املدعــي ‪ ،‬وأفهمــت املدعــي بــأن هــذا احلكــم ال مينــع‬\n      ‫املدعــى عليهــا مــن التقــدم للمحكمــة بطلــب الفــراق ‪ ،‬وقــررت بعــث‬\n\n\n‫‪161‬‬\n\f‫نســخة مــن احلكــم للغائــب عــن مجلــس القضــاء لتبليغهــا باحلكــم ‪،‬‬\n‫وإفهامهــا بــأن لهــا حــق االعتــراض علــى احلكــم خــال ثالثــن يومــا مــن‬\n‫تاريــخ اســتالمها نســخة احلكــم ‪ ،‬وإال ســقط حقهــا يف االعتــراض ‪،‬‬\n‫واكتســب احلكــم القطعيــة ‪ .‬وأقفلــت اجللســة الســاعة ‪ . 02 : 45‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                     ‫حــرر يف ‪1434/04/21‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )000‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة ففــي يــوم األربعــاء املوافــق ‪1434/7/19‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 8 : 15‬وفيهــا قــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫بخطــاب رئيســها رقــم وتاريخ ‪1434/6/24‬ه ـ وبالقرار رقم ‪34247377‬‬\n‫وتاريــخ ‪1434/6/20‬ه ـ ونصــه مــا يلــي ‪ ( :‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والئحتــه االعتراضيــة‪ ،‬تقــرر باألكثريــة إعادتهــا لفضيلــة‬\n‫حاكمهــا ملالحظــة مــا يلــي ‪ -1 :‬ادعــت املدعــى عليهــا بــأن املدعــي هــو‬\n‫الــذي طردهــا ووالــده هــو الــذي أقلهــا لبيــت أهلهــا واعتــرف املدعــي‬\n‫بــأن والــده هــو مــن أخذهــا علــى إثــر خــاف بينهمــا وقــد طلبهــا للرجــوع‬\n‫مرتــن وهــذا يــدل علــى وجــود خــاف بينهمــا فلــو طلــب منهمــا اختيــار‬\n‫حكمــن أو أحالهمــا إلــى جلنــة اإلصــاح لعــل اهلل يصلــح حالهمــا‬\n‫ويكــون لــه األجــر يف ذلــك ‪ -2 .‬لــم يعــرض مــا طلبتــه املدعــى عليهــا علــى‬\n‫املدعــي وهــو االعتــذار ‪ -3 .‬إذا احتــاج األمــر إلــى احلكــم باالنقيــاد فعلــى‬\n‫فضيلتــه إفهــام املــرأة بأنهــا إذا لــم متتثــل فإنهــا تعتبــر ناشــزا ويكــون ذلك‬\n‫موجبــا لســقوط حقوقهــا الزوجيــة مــا دامــت مصــره علــى عــدم االنقيــاد‬\n‫بنــاء علــى تعميــم الــوزارة رقــم ‪/8‬ت‪ 105/‬يف ‪1411/10/20‬ه ـ املــدون‬\n‫ضمــن التصنيــف املوضوعــي حــرف النــون (النشــوز )‪ - 4 .‬ذكــرت‬\n\n\n                                                                                         ‫‪162‬‬\n\f      ‫املدعــى عليهــا يف الالئحــة صــدور حكــم ضــد الــزوج برقــم ‪3322794‬‬\n      ‫يف ‪1433/5/3‬ه ـ ولــم جنــد فضيلتــه طلبــه أو أرفــق صــورة منــه والبــد‬\n      ‫مــن ذلــك ) أ‪ .‬ه ـ وعليــه أجيــب أصحــاب الفضيلــة فيمــا يخــص املالحظــة‬\n      ‫األولــى فقــد مت عــرض الصلــح عليهــا عــن طريــق قســم الصلــح وقــد قــرر‬\n      ‫أعضــاء اللجنــة اعتبــار املدعــى عليهــا ناشــز وأن عليهــا إعــادة املهر مقابل‬\n      ‫الفــراق ولكــن لعــدم حضــور املدعى عليها للجلســات مت احلكم عليها‪،‬‬\n      ‫وال ميلــك أحــد أن يفــرض علــى املــرأة أن تبــذل العــوض مقابــل فراقــه مــا‬\n      ‫لــم تختــر هــي ذلــك ‪ ،‬وفيمــا يخــص املالحظــة الثانيــة فقــد مت عــرض‬\n      ‫االعتــراض علــى املدعــي واســتعد لذلــك علــى مضــض بعــد محــاوالت ‪،‬‬\n      ‫ولكــن املدعــى عليهــا لــم حتضــر بعــد ذلــك ‪ ،‬وفيمــا يخــص املالحظــة‬\n      ‫الثالثــة فتعميــم وزيــر العــدل وهــو ميثــل الســلطة التنفيذيــة ال ينفــذ وجوبـ ًا‬\n      ‫علــى أعمــال القضــاء فيمــا يتعلــق بأحكامهــم‪ ،‬وتعاميــم الــوزارة ال تعــد‬\n      ‫وال حتصــى ‪ ،‬ويصعــب علــى املعنيــن العمــل بهــا جميعـ ًا الســيما وبعضهــا‬\n      ‫يعــارض بعــض ‪ ،‬عــاوة علــى عــدم علمــي بهــذا التعميــم ‪ ،‬وعلــى كل‬\n      ‫حــال فهــو إفهــام ال غضاضــه مــن ذكــره ‪ ،‬وعليــه فقــد قــررت إضافــة‬\n      ‫عبــارة اإلفهــام ونصهــا (وأفهمــت املدعــى عليهــا بأنهــا إذا لــم متتثــل فإنهــا‬\n      ‫تعتبــر ناشــز ًا ويكــون ذلــك موجبـ ًا لســقوط حقوقهــا الزوجيــة مــا دامــت‬\n      ‫مصــره علــى عــدم االنقيــاد)‪ ،‬وفيمــا يخــص املالحظــة الرابعــة فقــد‬\n      ‫أحضــر شــخص مــن طــرف املدعــي صــورة منــه ‪ ،‬ومت إرفاقهــا باملعاملــة‬\n      ‫وعليــه فلــم يظهــر لــي خــاف مــا أجريتــه ‪ ،‬وقــررت إحلــاق ذلــك علــى‬\n      ‫صــك احلكــم وســجله‪ ،‬وإعــادة املعاملــة حملكمــة االســتئناف لتدقيــق‬\n      ‫احلكــم بعــد األجــراء األخيــر وأقفلــت اجللســة الســاعة ‪ 8 : 25‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪163‬‬\n\f                                                       ‫حــرر يف ‪1434/7/19‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة ففــي يــوم‬\n‫األربعــاء املوافق‪1434/11/12‬ه ـ افتتحــت اجللســة الســاعة ‪ 9 : 45‬وفيهــا‬\n‫قــد عــادت املعاملــة مــن محكمــة االســتئناف بخطــاب رئيســها وتاريــخ‬\n‫‪1434/11/5‬ه ـ وبالقــرار وتاريــخ ‪1434/11/2‬ه ـ ومضمونــه مــا يلــي (‬\n‫وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة‬\n‫علــى احلكــم مــع مالحظــة التنبيــه املرفــق) وحتــى ال يخفــى جــرى أثباتــه‬\n‫وأقفلــت اجللســة الســاعة ‪ 9 : 55‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n              ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/12‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة وتاريــخ ‪1434/10/20‬ه املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ القاضــي باحملكمــة العامــة وتاريــخ ‪1434/4/21‬ه ـ ‪ ،‬املتضمــن‬\n‫دعــوى ضــد املــرأة يف العــودة لبيــت الزوجيــة‪ ،‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم مع مالحظة‬\n‫التنبيــه املرفــق ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n                                                               ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪164‬‬\n\f165\n\f166\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":158,"source_page_end":166,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"298d672ca9341be7226266a22e7356cf2f3bd59040626857a71d4e9511ee1bec","normalized_text_hash":"43ad6c17d18b4dfbb7b6b7ce689d6a81e2144875c02d9223e724cd98c26497ba","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p158-34194085"},{"id":"7b15dba6-4eaa-57ef-929a-dd0ebee0c925","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -عدم الدخول على الزوجة -طلب الزوجة فسخ النكاح لتغيب الزوج وعدم النفقة -شهادة الشهود ،وميني املدعية -للزوجة الفسخ إذا غاب عنها زوجها أكثر من ستة أشهر لغير عذر ،وإذا لم ينفق عليها زوجها دون مانع شرعي -احلكم غيابيا بفسخ النكاح دون عوض -الغائب على حجته متى حضر .","document_number":"33165950","case_number":"46510","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/3/30","year":"1434","subject":"فسخ نكاح -عدم الدخول على الزوجة -طلب الزوجة فسخ النكاح لتغيب الزوج وعدم النفقة -شهادة الشهود ،وميني املدعية -للزوجة الفسخ إذا غاب عنها زوجها أكثر من ستة أشهر لغير عذر ،وإذا لم ينفق عليها زوجها دون مانع شرعي -احلكم غيابيا بفسخ النكاح دون عوض -الغائب على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/3/30 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33165950 :‬‬\n                            ‫َر ْق ُم الدعوى‪46510 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34200213‬تاريخه‪1434/4/28:‬هـ‬\n\n\n      ‫فســخ نــكاح ‪ -‬عــدم الدخــول علــى الزوجــة ‪ -‬طلــب الزوجــة فســخ النــكاح‬\n      ‫لتغيب الزوج وعدم النفقة ‪ -‬شــهادة الشــهود ‪ ،‬وميني املدعية ‪ -‬للزوجة‬\n      ‫الفســخ إذا غــاب عنهــا زوجهــا أكثــر مــن ســتة أشــهر لغيــر عــذر ‪ ،‬وإذا لــم‬\n      ‫ينفــق عليهــا زوجهــا دون مانــع شــرعي ‪ -‬احلكــم غيابيــا بفســخ النــكاح‬\n                                   ‫دون عــوض ‪ -‬الغائــب علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n      ‫‪ .1‬قــال ابــن تيميــة يف الفتــاوى (‪« :)92/34‬إذا تعــذرت النفقــة مــن‬\n      ‫جهتــه فلهــا فســخ النــكاح فــإذا انقضــت عدتهــا تزوجــت بغيــره‪ ،‬والفســخ‬\n                                                                          ‫للحاكــم»‪.‬‬\n      ‫‪ .2‬قــال صاحــب كشــاف القنــاع « قلــت ‪ :‬مقتضــى مــا ســبق إذا غــاب‬\n      ‫فــوق نصــف ســنة يف غيــر غــزو أو حــج واجبــن ‪ ،‬أو طلــب رزق يحتاجــه‬\n      ‫وطلبــت قدومــه ولــم يقــدم فلهــا الفســخ‪ ،‬وإن لــم يقصــد املضــارة ‪ ،‬وأمــا‬\n      ‫قصــد املضــارة فتفســخ إذا مضــت األربعــة أشــهر وطلبــت الفيئــة وأبــى‬\n                                                        ‫علــى مــا تقــدم يف اإليــاء‪».‬‬\n      ‫‪ .3‬جــاء يف شــرح منتهــى اإلرادات (‪ :)237/3‬قولــه‪(« :‬أو غــاب موســر )‬\n      ‫عــن زوجتــه (وتعــذرت نفقتــه ) عليهــا بــأن لــم يتــرك لهــا نفقــة ولــم‬\n      ‫يقــدر لــه علــى مــال ‪ ،‬ولــم ميكنهــا حتصيــل نفقتهــا ( باســتدانة ) أي‬\n      ‫اقتــراض أو نحــوه عليــه ( وغيرهــا فلهــا الفســخ ) لتعــذر اإلنفــاق عليهــا‬\n      ‫مــن مالــه كحــال اإلعســار بــل أولــى وألن يف الصبــر ضــررا أمكــن إزالتــه‬\n\n‫‪167‬‬\n\f                                ‫بالفســخ فوجبــت إزالتــه دفعــا للضــرر»‬\n           ‫‪ .4‬الفقرة (ط) من املادة (‪ )18‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة املعــرف بهــا مــن قبــل والدهــا علــى املدعــى عليــه الغائــب‬\n‫عــن مجلــس احلكــم أنــه عقــد عليهــا قبــل خمــس عشــرة ســنة ولــم‬\n‫يدخــل بهــا‪ ،‬وأنهــا لــم تســتلم مــن مهرهــا شــيئا‪ ،‬وكان عمرهــا عنــد‬\n‫العقــد ثنتــي عشــرة ســنة وأنــه تركهــا طــوال هــذه املــدة بحجــة أنــه‬\n‫يبحــث عــن وظيفــة‪ ،‬ولــم ينفــق عليهــا إطالقــا وطلبــت احلكــم بفســخ‬\n‫نكاحهــا منــه ‪ ،‬مت االســتخالف لســماع جــواب املدعــى عليــه ‪ ،‬ورد‬\n‫جــواب االســتخالف املتضمــن عــدم تبلــغ املدعــى عليــه بعــد تطبيــق املــادة‬\n‫(‪/18‬ط) مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة ‪ ،‬كمــا‬\n‫جــرى اإلعــان عــن التبليــغ يف اجلريــدة ولــم يحضــر املدعــى عليــه أو مــن‬\n‫ينــوب عنــه ‪ ،‬بســؤال املدعيــة عــن بينتهــا أحضــرت شــاهدين ومت ســماع‬\n‫شــهادتهما‪ ،‬ومت تعديلهمــا ‪ ،‬مــا قــرره الفقهــاء أن للزوجــة الفســخ إذا‬\n‫غــاب عنهــا زوجهــا أكثــر مــن ســتة أشــهر لغيــر عــذر‪ ،‬ومــا قــرروه مــن أن‬\n‫الزوجــة لهــا الفســخ إذا لــم ينفــق عليهــا زوجهــا دون مانــع شــرعي ‪ ،‬حلــف‬\n‫املدعيــة اليمــن الشــرعية كمــا طلــب منهــا ‪ ،‬لــذا مت احلكــم بفســخ‬\n‫نــكاح املدعيــة مــن زوجهــا املدعــى عليــه الغائــب ‪ ،‬والغائــب علــى حجتــه‬\n‫متــى حضــر ‪ ،‬جــرى إفهــام املدعيــة أن ال تتــزوج حتــى يكتســب احلكــم‬\n‫القطعيــة وأنــه ال عــدة عليهــا ‪ ،‬بعــرض احلكــم علــى املدعيــة قــررت‬\n‫القناعــة ‪ ،‬بعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n                                                                                     ‫‪168‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )..........‬القاضــي يف احملكمــة‬\n      ‫العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بالريــاض برقــم ‪ 46510‬وتاريــخ ‪1431/11/4‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 31182453‬وتاريــخ ‪ 1431/11/04‬ه ـ ففــي‬\n      ‫يوم االثنني املوافق ‪ 1432/03/25‬هـ افتتحت اجللســة الســاعة ‪12 : 10‬‬\n      ‫وفيهــا حضــرت (‪ )..........‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ )..........‬املعــرف بهــا والدهــا (‪ )..........‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم (‪ )..........‬وادعــت علــى الغائــب (‪ )..........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ )..........‬قائلــة إن املدعــى عليــه يقيــم يف‬\n      ‫مدينــة عرعــر وقــد عقــد علــي قبــل خمــس عشــرة ســنة ولــم يدخــل بــي‬\n      ‫ولــم أســتلم مــن مهــري شــيئا وكان عمــري عنــد العقــد ثنتــي عشــرة ســنة‬\n      ‫وتركنــي طــوال هــذه املــدة بحجــة أنــه يبحــث عــن وظيفــة ولــم ينفــق علــي‬\n      ‫إطالقــا أطلــب احلكــم بفســخ نكاحــي منــه هــذه دعــواي وحيــث إن‬\n      ‫املدعــى عليــه يقيــم يف مدينــة عرعــر لــذا ســوف أســتخلف فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بعرعــر لســماع إجابــة املدعــى عليــه وإفادتنــا حضــرت‬\n      ‫املدعيــة املعــرف بــه والدهــا وقــد وردنــا خطــاب رئيــس احملكمــة العامــة‬\n      ‫يف عرعــر رقــم ‪ 321133531‬يف ‪ 1432/9/2‬ه ـ املتضمــن تطبيــق املــادة‬\n      ‫‪/18‬ط من نظام املرافعات الشــرعية ولوائحه التنفيذية وجرى مخاطبة‬\n      ‫إمــارة منطقــة احلــدود الشــمالية باخلطاب رقــم ‪ 9/1684‬يف ‪1432/6/20‬‬\n      ‫ه ـ ولــم يــرد رد ثــم جــرى اإلعالن عــن التبليغ يف صحيفة الرياض بعددها‬\n      ‫رقــم ‪ 15822‬وتاريــخ ‪1432/11/21‬ه ـ ولــم يحضــر املدعــى عليــه أو مــن‬\n\n‫‪169‬‬\n\f‫ينــوب عنــه لــذا قــررت إكمــال نظــر الدعــوى غيابيــا فســألت املدعيــة‬\n‫عــن بينتهــا فقالــت لــدي البينــة وســوف احضرهــا يف اجللســة القادمــة‬\n‫ثــم أحضــرت املدعيــة معهــا كال مــن ‪ ...........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ...........‬املولــود بتاريــخ ‪ 1399/12/17‬ويقيــم يف حي‬\n‫‪ ........‬ويعمــل يف القطــاع اخلــاص واملدعيــة أختــه الشــقيقة واملدعــى عليــه‬\n‫أبــن خالتــه و‪ ..................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫……‪ ..‬املولــود بتاريــخ ‪1406/09/11‬ه ـ ويقيــم يف حــي ‪ ........‬ويعمــل‬\n‫يف القطــاع اخلــاص واملدعيــة أختــه الشــقيقة واملدعــى عليــه ابــن خالتــه‬\n‫وشــهدا قائلــن نشــهد هلل أن املدعيــة تقيــم عنــد والدنــا منــذ عقــد عليهــا‬\n‫زوجهــا قبــل خمــس عشــرة ســنة تقريبــا ولــم يدخــل بهــا وقــد تركهــا‬\n‫املدعــى عليــه عنــد والدنــا وال نعلــم أنــه ينفــق عليهــا مــع أنهــا لــم متتنــع منــه‬\n‫هــذا مــا لدينــا مــن شــهادة ثــم أحضــرت املدعيــة معهــا ‪ ............‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬و‪ .............‬ســعودي اجلنســية‬\n‫مبوجب الســجل املدني رقم ‪ .........‬فشــهدا بعدالة وثقة الشــاهدين أعاله‬\n‫وقالــت املدعيــة ليــس لــدي ســوى مــا ذكــرت وليــس لــدي مــا أضيفــه‪ ،‬ثم‬\n‫يف يــوم األربعــاء املوافــق‪ 1433/03/23‬ه ـ افتتحت اجللســة الســاعة ‪: 15‬‬\n‫‪ 01‬وفيهــا حضــرت املدعيــة املعــرف بهــا والدهــا فطلبــت منهــا أن حتلــف‬\n‫علــى أن املدعــى عليــه الغائــب تركهــا عنــد أهلهــا مــدة خمــس عشــرة‬\n‫ســنة دون نفقــة وأنهــا لــم متتنــع منــه خــال هــذه املــدة فاســتعدت لذلــك ثــم‬\n‫حلفــت قائل ــة واهلل العظيــم ال ــذي ال إلــه إال هــو أن زوجــي املدعــى عليــه‬\n‫الغائــب تركننــي عنــد أهلــي مــدة خمــس عشــرة ســنة دون نفقــة وأننــي‬\n‫لــم امتنــع منــه خــال هــذه املــدة فبنــاء علــى الدعــوي ومــا تــدل عليــه‬\n‫شــهادة الشــاهدين املعدلــن شــرعا وحيــث مت التبليــغ صحيحــا وفقــا‬\n\n\n                                                                                                ‫‪170‬‬\n\f      ‫لنظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة وحيــث قــرر الفقهــاء‬\n      ‫أن للزوجــة الفســخ إذا غــاب عنهــا زوجهــا أكثــر مــن ســتة أشــهر لغيــر‬\n      ‫عــذر قــال صاحــب كشــاف القنــاع « قلــت ‪ :‬مقتضــى مــا ســبق إذا غــاب‬\n      ‫فــوق نصــف ســنة يف غيــر غــزو أو حــج واجبــن ‪ ،‬أو طلــب رزق يحتاجــه‬\n      ‫وطلبــت قدومــه ولــم يقــدم فلهــا الفســخ ‪ ،‬وإن لــم يقصــد املضــارة ‪ ،‬وأمــا‬\n      ‫قصــد املضــارة فتفســخ إذا مضــت األربعــة أشــهر وطلبــت الفيئــة وأبــى‬\n      ‫علــى مــا تقــدم يف اإليــاء‪ ».‬وبنــاء علــى مــا قــرره الفقهــاء مــن أن الزوجــة‬\n      ‫لهــا الفســخ إذا لــم ينفــق عليهــا زوجهــا دون مانــع شــرعي جــاء يف شــرح‬\n      ‫منتهــى اإلرادات ج ‪ 3‬ص ‪ 237‬قولــه «( أو غــاب موســر ) عــن زوجتــه (‬\n      ‫وتعــذرت نفقتــه ) عليهــا بــأن لــم يتــرك لهــا نفقــة ولــم يقــدر لــه علــى مــال ‪،‬‬\n      ‫ولــم ميكنهــا حتصيــل نفقتهــا ( باســتدانة ) أي اقتــراض أو نحــوه عليــه (‬\n      ‫وغيرهــا فلهــا الفســخ ) لتعــذر اإلنفــاق عليهــا مــن مالــه كحــال اإلعســار‬\n      ‫بــل أولــى وألن يف الصبــر ضــررا أمكــن إزالتــه بالفســخ فوجبــت إزالتــه‬\n      ‫دفعــا للضــرر» وقــال ابــن تيميــة يف الفتــاوى ج ‪ 34‬ص ‪ « 92‬إذا تعــذرت‬\n      ‫النفقــة مــن جهتــه فلهــا فســخ النــكاح فــإذا انقضــت عدتهــا تزوجــت‬\n      ‫بغيــره ‪ .‬والفســخ للحاكــم» وحيــث حلفــت اليمــن الشــرعية كمــا طلــب‬\n      ‫منهــا فبنــاء علــى مــا تقــدم كلــه فســخت نــكاح املدعيــة مــن زوجهــا‬\n      ‫الغائــب ‪ ................‬وبــه حكمــت والغائــب علــى حجتــه متــى حضــر‬\n      ‫وأفهمتهــا بــأن ال تتــزوج حتــى يكتســب احلكــم القطعيــة وأنــه ال عــدة‬\n      ‫عليهــا وبعــرض ذلــك علــى املدعيــة قــررت القناعــة وأمــا املدعــى عليــه فلــه‬\n      ‫حــق االعتــراض بطلــب التمييــز خــال ثالثــن يومــا اعتبــارا مــن تاريــخ‬\n      ‫تبليغــه باحلكــم وإذا تأخــر عــن هــذه املــدة ســقط حقــه يف االعتــراض‬\n      ‫بطلــب التمييــز واكتســب احلكــم القطعيــة وختمــت اجللســة الســاعة‬\n\n\n‫‪171‬‬\n\f‫‪ 01.30‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                               ‫وســلم‪ .‬حــرر يف ‪1433/3/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫بالريــاض وبــن طياتهــا قــرار الدائــرة األولــى املختصــة بنظــر قضايــا‬\n‫األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف بالريــاض رقــم‬\n‫‪ 33234825‬يف ‪1433/5/8‬ه ـ املتضمــن «‪ ..‬لوحــظ مــا يلــي أوال ‪ /‬لــم يتــم‬\n‫إرفــاق صــورة اإلعــان املنــوه عنــه يف الصــك ضمــن أوراق املعاملــة ‪.‬ثانيــا‬\n‫‪ /‬لــم يتــم إبالغــه حيــث انــه جــرى الكتابــة حملكمــة عرعــر وكتبــت‬\n‫احملكمــة إلمــارة املنطقــة ولــم جتيــب ولــم يجــر متابعــة مــن احملكمــة‬\n‫واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد والــه وصحبــه وســلم‬\n‫قاضــي اســتئناف‪ ............‬ختــم توقيــع قاضــي اســتئناف ‪ .............‬ختــم‬\n‫توقيــع قاضــي اســتئناف ‪ .........‬ختــم توقيــع وعليــه أجيــب أصحــاب‬\n‫الفضيلــة بــأن احملكمــة بلغــت املدعــى عليــه وفقــا لنظــام املرافعــات‬\n‫الشــرعية ولوائحــه التنفيذيــة ولكــون املدعــى عليــه ال يعــرف لــه عنــوان‬\n‫فتــم التبليــغ وفقــا للمــادة ‪/18‬ط‪ 4-3/‬ويعــد هــذا تبليــغ نظامــي وهــو‬\n‫مــا يســمى التبليــغ احلكمــي وأمــا أن احملكمــة تعقــب وتتابــع طلــب‬\n‫التبليــغ أو أنهــا توقــف القضيــة حلــن إفــادة اإلمــارة وان طالــت املــدة فهــذا‬\n‫ليــس لــه مســتند نظامــي ومــن الناحيــة الشــرعية فــان الغائــب مســافة‬\n‫قصــر يحكــم عليــه بالبينــة وأمــا امللحوظــة األولــى فقــد اجــري الــازم‬\n‫حيالهــا واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد والــه وصحبــه وســلم‪.‬‬\n‫حــرر يف ‪1433/6/8‬ه ـ احلمــد هلل وحــده وبعــد فقــد ســبق ان عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف بالريــاض وبــن طياتهــا قــرار الدائــرة‬\n‫األولــى املختصــة بتمييــز قضايــا األحــوال الشــخصية واإلنهــاءات رقــم‬\n\n\n                                                                                        ‫‪172‬‬\n\f      ‫‪ 33331625‬يف ‪1433/7/7‬ه ـ املتضمــن «‪ ..‬لوحــظ باألكثريــة انــه لــم‬\n      ‫يتــم بعــث احلكــم للمدعــى عليــه عــن طريــق اجلهــات املختصــة وتبليغــه‬\n      ‫باحلكــم حســبما نصــت عليــه التعليمــات واهلل املوفــق قاضــي اســتئناف‬\n      ‫‪ ............‬ختــم توقيــع قاضــي اســتئناف ‪ ............‬ختــم توقيــع لــه وجهــة نظــر‬\n      ‫رئيــس الدائــرة ‪ ...........‬ختــم توقيــع وعليــه جــرى الكتابــة باخلطــاب رقــم‬\n      ‫‪ 331606145‬يف ‪1433/8/27‬ه ـ إلــى احملكمــة العامــة بعرعــر لتســليم‬\n      ‫صــورة احلكــم إلــى املدعــى عليــه ثــم وردنــا خطــاب فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بعرعــر رقــم ‪ 34498780‬يف ‪1434/3/1‬ه ـ املتضمــن‬\n      ‫انــه جــرت مخاطبــة أميــر منطقــة احلــدود الشــمالية ومديــر شــرطة‬\n      ‫منطقــة احلــدود الشــمالية ومرجــع املدعــى عليــه وتبــن أن املدعــى عليــه‬\n      ‫كان يعمــل عســكريا باحلــرس الوطنــي بعرعــر وتقاعــد منــذ ســنوات‬\n      ‫طويلــة وال يوجــد لــه أي عنــوان ولــم تتمكــن احملكمــة وال إمــارة املنطقة‬\n      ‫وال اجلهــات األمنيــة مــن العثــور عليــه وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n      ‫علــى نبينــا محمــد حــرر يف ‪1434/3/25‬ه ـ احلمــد هلل وحــده وبعــد فقــد‬\n      ‫عــادت املعاملــة مــن محكمــة االســتئناف بالريــاض وقــد صــدق احلكــم‬\n      ‫مــن الدائــرة األولــى لتمييــز قضايــا األحــوال الشــخصية واإلنهــاءات‬\n      ‫مبحكمــة االســتئناف بالريــاض مبوجــب قرارهــا رقــم ‪34200213‬‬\n      ‫يف ‪1434/04/28‬ه ـ قاضــي اســتئناف ‪ ..........‬ختــم وتوقيــع ولــه وجهــة‬\n      ‫نظــر قاضــي اســتئناف ‪ ............‬ختــم وتوقيــع رئيــس الدائــرة ‪ ........‬ختــم‬\n      ‫وتوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/18‬ه ـ احلمــد هلل وحــده وبعــد ‪ ..‬فقد‬\n      ‫اطلعنــا نحــن قضــاة الدائــرة األولــى التمييــز قضايــا األحــوال الشــخصية‬\n      ‫واالنهــاءات مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n\n\n‫‪173‬‬\n\f‫فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد رقــم ‪34657226‬‬\n‫وتاريــخ ‪1434/4/15‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n‫باحملكمــة الشــيخ ‪ ............. /‬املســجل برقــم ‪ 33165950‬وتاريــخ‬\n‫‪1433/3/30‬ه ـ اخلــاص بدعــوى ‪ ............. /‬ضــد ‪ ............. /‬بشــأن طلــب‬\n‫املدعيــة فســخ نكاحهــا مــن املدعــى عليــه ‪ ،‬وقــد تضمــن الصــك أن‬\n‫فضيلتــه فســخ نــكاح املدعيــة مــن املدعــى عليــه وبــه حكــم ‪ ..‬إلــخ ‪.‬‬\n‫وحيــث ســبقت دارســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق العاملــة وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه‬\n‫علــى الصــك وصــورة ضبطــه بتاريــخ ‪1434/3/25‬ه ـ بنــاء قــرار الدائــرة‬\n‫رقــم ‪ 33331625‬وتاريــخ ‪1433/7/7‬ه ـ لــم يظهــر مــا يوجــب االعتــراض‬\n     ‫‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪174‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":167,"source_page_end":174,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9c13bda70ddb49f3d378d1bc60cb96637c4c2a3328035f8b0f5d76bc15b0b5df","normalized_text_hash":"1b522ed5a357a3b8754b583f7e7b814f64749ee96ac52da3008602555ad12003","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p167-33165950"},{"id":"4e0498ca-4b10-55eb-b1e5-4067f78f2e8f","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب الزوجة فسخ النكاح قبل الدخول واخللوة لتعاطي الزوج املخدرات -وجود سوابق على الزوج -جرمية املخدرات تعد عيب ا شرعي ا موجبا للفسخ -احلكم بفسخ نكاح املدعية بغير عوض .1القاعدة الفقهية الكلية :ال ضرر وال ضرار .","document_number":"33389019","case_number":"3339563","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/21","year":"1434","subject":"فسخ نكاح -طلب الزوجة فسخ النكاح قبل الدخول واخللوة لتعاطي الزوج املخدرات -وجود سوابق على الزوج -جرمية املخدرات تعد عيب ا شرعي ا موجبا للفسخ -احلكم بفسخ نكاح املدعية بغير عوض .1القاعدة الفقهية الكلية :ال ضرر وال ضرار .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/8/21 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33389019 :‬‬\n                          ‫َر ْق ُم الدعوى‪3339563 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34271675‬تاريخه‪1434/7/18 :‬هـ‬\n\n\n      ‫فســخ نكاح ‪ -‬طلب الزوجة فســخ النكاح قبل الدخول واخللوة لتعاطي‬\n      ‫الــزوج املخــدرات ‪ -‬وجــود ســوابق علــى الــزوج ‪ -‬جرميــة املخــدرات تعــد‬\n      ‫عيبـ ًا شــرعي ًا موجبــا للفســخ ‪ -‬احلكــم بفســخ نــكاح املدعيــة بغيــر عوض‬\n\n\n\n\n                            ‫‪ .1‬القاعدة الفقهية الكلية‪ :‬ال ضرر وال ضرار ‪.‬‬\n                            ‫‪ .2‬القاعدة الفقهية الفرعية بأن الضرر يزال ‪.‬‬\n         ‫‪ .3‬املادة ‪/10/34‬هـ من نظام املرافعات الشرعية‪ ،‬ولوائحه التنفيذية‬\n\n\n\n\n      ‫ادعــت املدعيــة علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم أنــه عقــد‬\n      ‫عليهــا ‪ ،‬ولــم يدخــل عليهــا ولــم يخــل بهــا ‪ ،‬وبعــد ثالثــة أســابيع اتصلــت‬\n      ‫بــه ولــم يجــب علــى اتصالهــا‪ ،‬واتصلــت علــى أهلــه وأخبروهــا بعــد‬\n      ‫مراوغــة أنــه مســجون‪ ،‬وأن املدعــى عليــه اتصــل عليهــا مــن الســجن ليلــة‬\n      ‫العيــد وأخبرهــا أنــه مســجون يف قضيــة وســاطة حشــيش ‪ ،‬وبعــد تقصــي‬\n      ‫املوضــوع علمــت أنــه ســجن يف قضيــة حبــوب ‪ ،‬وقــررت أنهــا لــم تكــن‬\n      ‫تعلــم بذلــك ‪ ،‬وطلبــت فســخ نكاحهــا منــه‪ ،‬واســتعدت بإعــادة املهــر‬\n      ‫وقــدره عشــرون ألــف ريــال ‪ ،‬مت االســتخالف لســماع جــواب املدعى عليه‬\n      ‫‪ ،‬ولــم يــرد جــواب االســتخالف ‪ ،‬ورد خطــاب مديــر إدارة مكافحــة‬\n\n‫‪175‬‬\n\f‫املخــدرات املتضمــن وجــود ســابقتني علــى املدعــى عليــه ســابقة حيــازة‬\n‫مخــدرات ‪ ،‬والســابقة الثانيــة اتهــام ‪ ،‬بعرضهــا علــى املدعيــة قــررت‬\n‫أنهــا كانــت جتهــل ســوابقه‪ ،‬وتبــن لهــا اآلن غشــه وأنــه غيــر كفــؤ‬\n‫وطلبــت فســخ نكاحهــا منــه ‪ ،‬جــرى االطــاع علــى عقــد النــكاح بــن‬\n‫الطرفــن املتضمــن عقــد النــكاح علــى مهــر قــدره عشــرون ألــف ريــال‬\n‫ســعودي مســتلمة ومؤخــر صــداق عشــرون ألــف ريــال ســعودي ‪ ،‬ملــا يف‬\n‫هــذه اجلرميــة مــن خطــر علــى الفــرد واملجتمــع ‪ ،‬هــذه اجلرميــة تعــد عيب ـ ًا‬\n‫شــرعي ًا موجبــا للفســخ قياس ـ ًا لألولــى وللقاعــدة الفقهيــة الكليــة بأنــه‬\n‫ال ضــرر وال ضــرار وللقاعــدة الفقهيــة الفرعيــة بــأن الضــرر يــزال ‪ ،‬يف‬\n‫بقــاء املدعيــة واحلالــة مــا ذكــر تعليــق لهــا وإضــرار بهــا علــى وجــه متنعــه‬\n‫الشــريعة‪ ،‬والشــريعة اإلســامية جــاءت بتحصيــل املصالــح وتكثيرهــا‬\n‫ودرء املفاســد وتقليلهــا ‪ ،‬مت احلكــم بفســخ نــكاح املدعيــة مــن زوجهــا‬\n‫املدعــى عليــه بغيــر عــوض ‪،‬جــرى إفهــام الزوجــة بأنهــا بانــت مــن زوجهــا‬\n‫بينون ـ ًة صغــرى ال حتــل لــه إال بعقــد ومهــر جديديــن يعتبــر فيهمــا‬\n‫األركان والشــروط وأنهــا ال حتــل لــأزواج حتــى يكتســب احلكــم‬\n‫القطعيــة ‪ ،‬وأنهــا ال عــدة عليهــا لعــدم الدخــول أو اخللــوة ‪ ،‬بعــد رفــع‬\n                          ‫احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n                                                                                         ‫‪176‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).......‬القاضــي باحملكمــة العامــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جــدة (‪ ).......‬املســاعد برقــم ‪3339563‬‬\n      ‫وتاريــخ ‪ 1433/01/16‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33100349‬وتاريــخ‬\n      ‫‪1433/1/16‬ه ـ ويف ه ــذا ال ــيوم االثنــن املوافـ ــق ‪1433/01/24‬ه ـ‬\n      ‫افتتحــت اجللســة الساع ــة ‪ 11 : 26‬وفيهــا حضــرت (‪ ).......‬فلســطينية‬\n      ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪ ).......‬ولــم يحضــر املدعــى عليــه‬\n      ‫‪ .‬وادعــت املدعيــة قائلــة يف دعواهــا أن املدعــى عليــه عقــد النــكاح علــي‬\n      ‫يف تاريــخ ‪1432/10/22‬ه ـ ولــم يدخــل علــي ولــم يخــل بــي وبعــد ثالثــة‬\n      ‫أســابيع أتصلــت بــه ولــم يجــب علــى أتصالــي وقــد أتصلــت علــى أهلــه‬\n      ‫وأخبرونــي بعــد مراوغــة أنــه مســجون يف املدينــة املنــورة وقــد أتصــل‬\n      ‫علــي املدعــى عليــه مــن الســجن ليلــة العيــد وأخبرنــي أنــه مســجون يف‬\n      ‫قضيــة وســاطة حشــيش وقــد قمــت بإرســال زوج أختــي لتقصــي املوضــوع‬\n      ‫فعلمنــا أن املدعــى عليــه ســبق أن ســجن يف قضيــة حبــوب ‪ ،‬وحيــث‬\n      ‫أننــي لــم أكــن أعلــم بذلــك ولــم يســبق لــي أن أخبرنــي أنــه يتعاطــى‬\n      ‫أو يعمــل يف احلشــيش وهــو اآلن مســجون يف املدنيــة املنــورة لــذا أطلــب‬\n      ‫فســخ نكاحــي منــه ومســتعدة إلعــادة املهــر هــذه دعــواي ‪ .‬وإســتناد ًا إلــى‬\n      ‫املــادة ‪/10/34‬ه ـ مــن نظــام املرافعــات الشــرعية واللوائــح التنفيذيــة لــه‬\n      ‫وألن املدعــى عليــه يف املدينــة املنــورة فقــد قــررت إســتخالف فضيلــة‬\n      ‫رئيــس احملكمــة العامــة يف املدينــة املنــورة أو مــن ينيبــه لعــرض دعــوى‬\n      ‫املدعيــة علــى املدعــى عليــه ورصــد إجابتــه عليهــا ومــن ثــم بعــث صــورة‬\n\n‫‪177‬‬\n\f‫مصدقــة مــن الضبــط إلينــا إلكمــال النظــر ويف جلســة اخــرى حضــرت‬\n‫املدعيــة أصالــة وحضــرت والدتهــا ‪.............‬فلســطينية اجلنســية مبوجــب‬\n‫رخصــة اإلقامــة رقــم ‪ . ..............‬ولــم يردنــا جــواب مــن محكمــة املدينــة‬\n‫املنــورة علــى إســتخالفنا الــذي بعــث إليهــم ‪ ،‬وســيتم كتابــة خطــاب‬\n‫إحلاقــي لفضيلــة رئيــس احملكمــة العامــة باملدينــة املنــورة لإلفــادة عــن‬\n‫جــواب املدعــى عليــه جتــاه دعــوى املدعيــة ‪ ،‬وقــد قــررت املدعيــة قائلــة‬\n‫‪ :‬إننــي أرغــب يف اخللــع بكامــل املهــر وقــدره ‪ 20.000‬عشــرون ألــف‬\n‫ريــال هكــذا قــررت ‪ .‬فجــرى منــا ســؤال املدعيــة عــن عقــد النــكاح أو‬\n‫صــورة منــه ‪ ،‬فأجابــت قائلــة ‪ :‬ليــس لــدي عقــد النــكاح فهــو يكــون‬\n‫معــه يف حــوزة الــزوج وليــس لــدي صــورة مــن عقــد النــكاح ألن زوجــي‬\n‫قبــض عليــه يف جرعــة مخــدرات وال زال مســجون مــن تاريخــه وأطلــب‬\n‫مــن فضيلتكــم الكتابــة إلــى إدارة مكافحــة املخــدرات لإلفــادة عــن‬\n‫ســجل املذكــور لديهــم ‪ ،‬هكــذا أجابــت ‪ .‬وألجــل مــا ذكــر قــررت رفــع‬\n‫اجللســة إلرســال خطــاب إحلاقــي للمحكمــة العامــة باملدينــة لإلفــادة عــن‬\n‫جــواب املدعــى عليــه وإرســال خطــاب إلدارة مكافحــة املخــدرات بجــدة‬\n‫لإلفــادة عــن ســجل املذكــور ويف جلســة اخــرى املدعيــة وحضــرت معهــا‬\n‫والدتهــا ‪ ............‬فلســطينية اجلنســية باإلقامــة رقــم …………‪ .‬ولــم‬\n‫يحضــر املدعــى عليــه وكان قــدر وردنــا خطــاب مديــر إدارة مكافحــة‬\n‫املخــدرات بجــدة برقــم ‪ 6885‬يف ‪1433/6/8‬ه ـ املتضمــن ( أتضــح لنــا‬\n‫بجهــاز احلاســب اآللــي وجــود ســابقتان كمــا يتضــح مــن البرنــت املرفقــة‬\n‫وباالطــاع علــى ســجل الســوابق املرفــق وجــد أن الســابقة األولــى‬\n‫هــي حيــازة مخــدرات وتاريخهــا ‪1429/10/19‬ه ـ ومــكان الضبــط‬\n‫خميــس مشــيط وقــد حكــم عليــه مــن احملكمــة املختصــة بســجن ‪7‬‬\n\n\n                                                                                      ‫‪178‬‬\n\f      ‫اشــهر وجلــد ‪ 70‬جلــده واعفــى مــن االبعــاد كونــه طالــب ‪ .‬كمــا وجــد‬\n      ‫أن الســابقة الثانيــة هــي ترويــج مخــدرات وتاريخهــا ‪1432/11/21‬‬\n      ‫ومــكان الضبــط املدينــة املنــورة ولــم يحكــم عليــه مــن تاريخــه ‪ ) .‬وقــد‬\n      ‫جــرى تــاوة اخلطــاب علــى املدعيــة مــع ســجل الســوابق فقــررت املدعيــة‬\n      ‫قائل ـ ًة أننــي كنــت أجهــل ســوابقه وقــد تبــن لــي اآلن غشــه وأنــه غيــر‬\n      ‫كفــأ وأنــا ال أريــد أن ألــوث ســمعتي وســمعة عائلتــي بهــذا اجلــرم وأطلــب‬\n      ‫فســخ نكاحــي منــه هكــذا قــررت‪ ،‬وبنــاء علــى مــا تقــدم وبعــد االطــاع‬\n      ‫علــى الســجل اجلنائــي للمدعــى عليــه املشــفوع بخطــاب مديــر مكافحــة‬\n      ‫املخــدرات بجــدة رقــم ‪ 6885‬وتاريــخ ‪1433/6/8‬ه ـ املتضمــن اعتــراف‬\n      ‫املدعــى عليــه جلرميــة الترويــج التعاطــي املخــدرات وملــا يف هــذه اجلرميــة مــن‬\n      ‫خــط علــى الفــرد واملجتمــع وألن هــذه اجلرميــة تعــد عيب ـ ًا شــرعي ًا موجبــا‬\n      ‫للفســخ واحلالــة مــا ذكــر يف الدعــوى قياسـ ًا لألولــى وللقاعــدة الفقهيــة‬\n      ‫الكليــة بأنــه ال ضــرر وال ضــرار وللقاعــدة الفقهيــة الفرعيــة بــأن الضرر‬\n      ‫يــزال وملــا يف بقــاء املدعيــة واحلالــة مــا ذكــر مــن تعليــق لهــا وإضــرار بهــا‬\n      ‫علــى وجــه متنعــه الشــريعة ‪ ،‬وألن الشــريعة اإلســامية جــاءت بتحصيــل‬\n      ‫املصالــح وتكثيرهــا ودرء املفاســد وتقليلهــا ‪ ،‬لــكل ذلــك فقــد فســخت‬\n      ‫نــكاح املدعيــة مــن زوجهــا املدعــى عليــه بغيــر عــوض وبذلــك حكمــت‬\n      ‫‪ .‬وأفهمــت الزوجــة بأنهــا قــد بانــت مــن زوجهــا بينون ـ ًة صغــرى ال حتــل‬\n      ‫لــه إال بعقــد ومهــر جديديــن يعتبــر فيهمــا األركان والشــروط كمــا‬\n      ‫أفهمتهــا بأنهــا ال حتــل لــأزواج حتــى يكتســب احلكم القطعيــة النهائية‬\n      ‫وســيتم بعــث صــورة مــن احلكــم إلــى املدعــى عليــه لتقريــر القناعــة مــن‬\n      ‫عدمهــا وأن لــه حــق االعتــراض خــال ثالثــن يومـ ًا مــن تاريــخ اســتالمه‬\n      ‫احلكــم وإكمــال مــا يلــزم بعــد ذلــك بحســب النظــام وبــاهلل التوفيــق ‪.‬‬\n\n\n‫‪179‬‬\n\f‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n              ‫ـاء وبــاهلل التوفيــق‪.‬‬\n                                  ‫‪1433/08/14‬ه ـ ‪ ،..‬الســاعة ‪12 : 10‬مسـ ً‬\n‫ويف هــذا اليــوم الســبت املوافــق‪ 1433/11/27‬ه ـ وحيــث جــرى منــا‬\n‫إرســال صــورة احلكــم رقــم ‪ 33389019‬وتاريــخ ‪1433/8/21‬ه ـ الــى‬\n‫املدعــى عليــه بخطابنــا رقــم ‪ 33/1641323‬يف ‪1433/09/03‬ه ـ وحتــى‬\n‫تاريخــه لــم تردنــا الئحــة اعتراضيــة مــن املدعــى عليــه ‪ ،‬لــذا ســوف ترفــع‬\n‫كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫حــرر يف ‪1433/11/27‬ه ـ ‪ .‬ويف يــوم األربعــاء املوافــق ‪1434/02/27‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09 : 15‬وفيهــا حضــرت املدعيــة ‪.............‬‬\n‫فلســطينية اجلنســية مبوجــب مــا مت ضبطــه يف جلســة ســابقة أصالــة‬\n‫واملعــرف بهــا مــن قبــل والدهــا ‪ ..........‬فلســطيني اجلنســية مبوجب رخصة‬\n‫اإلقامــة رقــم ‪ ...............‬ولــم يحضــر املدعــى عليــه ‪ . ..............‬وكان قــد‬\n‫وردتنــا املعاملــة مــن محكمــة االســتئناف بخطابهــم رقــم ‪332221007‬‬\n‫وتاريــخ ‪1434/01/14‬ه ـ واملقيــدة لدينــا برقــم ‪ 34/194734‬وتاريــخ‬\n‫‪1434/01/24‬ه ـ واملرفــق بهــا القــرار الصــادر مــن دائــرة األحــوال‬\n‫الشــخصية األولــى برقــم ‪ 346539‬وتاريــخ ‪1434/01/10‬ه ـ املتضمــن‬\n‫مالحظــة مــا يلــي ‪ -1 (( :‬لــم يذكــر يف صــك احلكــم وال ضبطــه أســم‬\n‫املدعــى عليــه وال هويتــه أو جنســيته ‪ -2 .‬لــم يتحقــق فضيلتــه مــن عقــد‬\n‫النــكاح وال ســجله ولــم يطلــب بينــة مــن املدعيــة وإمنــا أكتفــى مبــا ورد‬\n‫يف الدعــوى ‪-3 .‬أشــار فضيلتــه إلــى أنــه تقــرر اإلســتخالف لســماع إجابــة‬\n‫املدعــى عليــه ولــم يظهــر مــن أوراق املعاملــة أي خطــاب اســتخالف أو‬\n‫أي تعقيــب عليــه ‪ -4 .‬طلبــت املدعيــة فســخ النــكاح مقابــل إعــادة املهــر‬\n\n\n                                                                                          ‫‪180‬‬\n\f      ‫وحكــم فضيلتــه بخــاف ذلــك ولــم يظهــر مــا مينــع مــن إجابــة طلبهــا‬\n      ‫احتياط ـ ًا لفســخ النــكاح إذا ظهــر مــا يســوغ احلكــم بــه ‪ -5 .‬ذكــر‬\n      ‫فضيلتــه يف حيثيــات احلكــم أن املدعــى عليــه أعتــرف بجرميــة ترويــج‬\n      ‫وتعاطــي املخــدرات بنــاء علــى خطــاب مديــر مكافحــة املخــدرات بجــدة‬\n      ‫رقــم ‪ 6885‬يف ‪1433/06/08‬ه ـ ولــم يظهــر أي ســابقة ترويــج يف اخلطاب‬\n      ‫املذكــور أو البرنــت املرفــق وإمنــا ســابقة حيــازة ولــم يظهــر منــه أي‬\n      ‫ســابقة أخــرى وإمنــا ظهــر أنــه ســجني بســبب تهمــة لــم يحكــم بهــا وال‬\n      ‫يخفــى أن التهمــة ال تعــد ســابقة مــا لــم يحكــم بثبوتهــا ويلــزم إعــادة‬\n      ‫النظــر يف اخلطــاب املذكــور وســجل الســوابق املرفــق بــه وتصحيــح‬\n      ‫مــا جــرى رصــده خاصــة وهــو مســتند مــا مت احلكــم بــه دون أي بينــة‬\n      ‫أخــرى ‪ -6 .‬لــم يفهــم فضيلتــه املدعيــة بأنــه ال عــدة عليهــا إذا لــم يظهــر‬\n      ‫خــاف مــا ذكرتــه مــن عــدم الدخــول أو اخللــوة ‪ -7‬يلــزم إبــاغ املدعــى‬\n      ‫عليــه بالدعــوى وســماع جوابــه عليهــا مــا دام قــد ظهــر أنــه ســجني يف‬\n      ‫املدينــة املنــورة كمــا لــم يظهــر مــن أوراق املعاملــة أنــه جــرى الكتابــة‬\n      ‫إلبالغــه باحلكــم مــع متكينــه مــن تقــدمي الئحتــه ولــم يظهــر مســتند‬\n      ‫مــا جــرى اإلشــارة إليــه يف الضبــط وصــك احلكــم خالف ـ ًا لذلــك )) ‪.‬‬\n      ‫ولوجاهــة مــا ذكــره أصحــاب الفضيلــة فــإن اســم املدعــى عليــه هــو‬\n      ‫‪...............‬فلســطيني اجلنســية مبوجــب اإلقامــة رقــم ‪ ، ..........‬وفيمــا‬\n      ‫يخــص املالحظــة الثانيــة فقــد أحضــرت املدعيــة صــورة طبــق األصــل‬\n      ‫لعقــد النــكاح رقــم‪ .............‬وتاريــخ ‪1432/10/22‬ه ـ واملصــدق مــن قبل‬\n      ‫احملكمــة اجلزئيــة للضمــان واألنكحــة بجــدة بتاريــخ ‪1433/03/26‬ه ـ‬\n      ‫املتضمــن ((حضــر ‪ ................‬فلســطيني اجلنســية إقامــة رقــم ‪...........‬‬\n      ‫وطلــب عقــد نكاحــه علــى املــرأة البكــر البالــغ ‪ ....... /‬فلســطينية‬\n\n\n‫‪181‬‬\n\f‫اجلنســية إقامــة رقــم ‪ ...............‬تاريــخ امليــاد ‪1406/05/11‬ه ـ حيــث‬\n‫قبلــت ورضيــت بــه زوج ـ ًا بحضــور وليهــا الشــرعي والدهــا ‪.......... /‬‬\n‫فلســطيني اجلنســية مبوجــب إقامــة رقــم ‪ . ............‬وذلــك علــى مهــر قــدره‬\n‫عشــرون ألــف ريــال ســعودي مســتلمة ومؤخــر صــداق عشــرين ألــف ريــال‬\n‫ســعودي )) ‪ .‬وأمــا املالحظــة الثالثــة فقــد ســبق منــا اســتخالف فضيلــة‬\n‫رئيــس احملكمــة العامــة باملدينــة املنــورة بخطابنــا رقــم ‪33/189180‬‬\n‫وتاريــخ ‪1433/01/30‬ه ـ ومبوجــب خطابنــا رقــم ‪ 33654132‬وتاريــخ‬\n‫‪1433/04/12‬ه ـ ‪ .‬وأمــا املالحظــة الرابعــة فقــد جــرى عرضهــا علــى‬\n‫املدعيــة فأجابــت بقولهــا ‪ :‬إننــي كنــت مســتعدة قبــل أن يثبــت عليــه‬\n‫ســابقة مخــدرات أمــا اآلن فهــو ال يســتاهل شــيء وهــو غيــر كفــأ ‪ .‬وأمــا‬\n‫مــا يخــص املالحظــة اخلامســة فصحــة الســوابق اجلنائيــة علــى املدعــى‬\n‫عليــه كمــا هــو موضــح يف خطــاب مديــر إدارة مكافحــة املخــدرات‬\n‫هــي ‪ :‬ســابقة حيــازة مخــدرات وتاريــخ الضبــط يف ‪1429/10/19‬ه ـ يف‬\n‫خميــس مشــيط وقــد حكــم عليــه بالســجن ســبعة أشــهر واجللــد ‪70‬‬\n‫جلــدة وأعفــي عــن اإلبعــاد كونــه طالب ـ ًا والســابقة الثانيــة اتهــام وأمــا‬\n‫مــا يخــص املالحظــة السادســة فقــد جــرى منــا إفهــام املدعيــة يف هــذه‬\n‫اجللســة بأنــه ال عــدة عليهــا لعــدم الدخــول أو اخللــوة ‪ .‬وأمــا املالحظــة‬\n‫الســابعة فأجيــب أصحــاب الفضيلــة بأنــه ســبق بعــث الدعــوى للمدعــى‬\n‫عليــه ألخــذ جوابــه يف العــام املاضــي باخلطــاب رقــم ‪ 33/189180‬وتاريــخ‬\n‫‪1433/01/30‬ه ـ وعقــب عليــه مــرة أخــرى ألخــذ جوابــه وذلــك مبوجــب‬\n‫خطابنــا رقــم ‪ 33/654132‬وتاريــخ ‪1433/4/12‬ه ـ كمــا جــرى منــا‬\n‫تبليــغ املدعــى عليــه باحلكــم مبوجــب خطابنــا رقــم ‪33/1641323‬‬\n‫وتاريــخ ‪1433/09/04‬ه ـ ‪ ،‬وأمــا مــا يخــص اإلشــارة إلــى ذلــك يف‬\n\n\n                                                                                     ‫‪182‬‬\n\f      ‫الضبــط والصــك والســجل فقــد جــرى منــا إكمــال ذلــك والتهميــش بــه‬\n      ‫علــى صكــه وضبطــه وســجله ‪ .‬وعليــه فقــد قــررت إعــادة املعاملــة إلــى‬\n      ‫أصحــاب الفضيلــة وفقهــم اهلل ورعاهــم ‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/2/27‬ه ـ ‪.‬‬\n      ‫ويف يــوم االثنــن املوافــق ‪1434/06/26‬ه ـ افتتحــت اجللســة الســاعة ‪15‬‬\n      ‫‪ 09 :‬وفيهــا حضــرت املدعيــة أصالــة وحضــر والــد املدعيــة املعــرف بهــا‬\n      ‫‪ ،‬ولــم يحضــر املدعــى عليــه ‪ ..............‬وال مــن ينــوب عنــه ‪ .‬وكان قــد‬\n      ‫وردتنــا املعاملــة مــن محكمــة االســتئناف بخطابهــم رقــم ‪34194734‬‬\n      ‫وتاريــخ ‪1434/05/29‬ه ـ املقيــد لدينــا برقــم ‪ 34/194734‬وتاريــخ‬\n      ‫‪1434/06/05‬ه ـ املرفــق بــه قرارهــم الصــادر مــن دائــرة األحــوال‬\n      ‫الشــخصية األولــى برقــم ‪ 34219684‬وتاريــخ ‪1434/5/22‬ه ـ املتضمــن‬\n      ‫مالحظــة مــا يلــي‪(( :‬تقــرر باألكثريــة إعادتهــا لفضيلــة حاكمهــا‬\n      ‫ملالحظــة أنــه لــم يظهــر مــن أوراق املعاملــة مــا ورد يف جــواب فضيلتــه‬\n      ‫علــى املالحظتــن الثالثــة والســابعة مــع أهميــة مــا ورد فيهمــا فلــم يظهــر‬\n      ‫أي اســتخالف لســماع جــواب املدعــى عليــه كمــا لــم يظهــر أنــه جــرى‬\n      ‫الكتابــة إلبــاغ املدعــى عليــه باحلكــم ولــم يظهــر أنــه تبلــغ بالدعــوى‬\n      ‫أو احلكــم كمــا يظهــر مــا مينــع إجابــة طلــب املدعيــة بإعــادة املهــر ومــا‬\n      ‫ورد يف جوابهــا األخيــر مخالــف ملــا ورد يف الئحــة وينبغــي االحتيــاط‬\n      ‫لفســخ النــكاح بــدون أي عــوض خاصــة وقــد جــرى اإلشــارة إلــى أنــه‬\n      ‫قبــل الدخــول واخللــوة ‪ . )) .‬عليــه أجيــب أصحــاب الفضيلــة فيمــا يخــص‬\n      ‫املالحظــة بعــدم الكتابــة منــا لإلســتخالف لســماع اجلــواب املدعى عليه‬\n      ‫‪ ،‬بأنــه ســبق منــا اإلجابــة بأنــه قــد جــرى بعــث اإلســتخالف للمحكمــة‬\n      ‫العامــة باملدينــة املنــورة برقــم ‪ 33/189180‬وتاريــخ ‪1433/1/30‬ه ـ ولــم‬\n\n\n‫‪183‬‬\n\f‫يردنــا منهــم جــواب ‪ ،‬وجــرى بعــث خطــاب إحلاقــي تعقيبــي لســماع جــواب‬\n‫املدعــى عليــه وذلــك بخطابنــا رقــم ‪ 33654132‬وتاريــخ ‪1433/04/12‬هـ‬\n‫ولــم يردنــا منهــم إجابــة ‪ .‬ومعلــوم لــدى أصحــاب الفضيلــة أن املعاملــة‬\n‫ال تبعــث للقاضــي املســتخلف بــل يبعــث خطــاب بذلــك مــع صــورة‬\n‫مصدقــة مــن الضبــط ‪ ،‬وألنــه لــم يــرد مــن اجلهــة املســتخلفة جــواب علــى‬\n‫خطابنــا وال إعــادة خلطاباتنــا إليهــم فلــم يلحــق يف املعاملــة ذلــك ‪ .‬وأمــا‬\n‫مــا يخــص تبليــغ املدعــى عليــه باحلكــم فقــد جــرى منــا اإلجابــة مســبق ًا‬\n‫علــى أصحــاب الفضيلــة حفظهــم اهلل بأنــه قــد جــرى منــا بعــث خطــاب‬\n‫للمدعــى عليــه لتبليغــه بنســخة مــن احلكــم وذلــك مبوجــب خطابنــا‬\n‫رقــم ‪ 33/1641323‬وتاريــخ ‪1433/9/4‬ه ـ ‪ .‬وأمــا مــا يخــص املالحظــة‬\n‫األخيــرة فقــد جــرى عرضهــا علــى املدعيــة احلاضــرة فأجابــت بقولهــا‬\n‫‪ :‬كيــف يطلــب قضــاة االســتئناف أن أعيــد لــه كامــل املهــر والفــراق‬\n‫قبــل الدخــول ؟ واملشــايخ مركزيــن أننــي طلبــت يف صحيفــة الدعــوى‬\n‫شــيء ثــم عدلتــه وأنــا ســبق جاوبــت بأنــي ملــا طلبــت مــا كنــت أعــرف‬\n‫عــن وضعــه باملخــدرات ‪ ،‬فكيــف يرضــى املشــايخ أن أعيــد لهــم شــيء‬\n‫مــن مهــره وهــو مــن أهــل املخــدرات ؟ والشــرع أشــترط الكفــاءة وشــرع‬\n‫الفــراق ألجــل عــدم الكفــاءة وهــذا غيــر كفــأ وال يســتحق شــيئ ًا وأنــا‬\n‫معلقــة ومتضــررة بســبب غشــه وتدليســه علــي ‪ ،‬وحســبي اهلل ‪ .‬هكــذا‬\n‫أجابــت ‪ .‬وعليــه فإننــي مــا زلــت علــى مــا حكمــت بــه وقــررت إعــادة‬\n‫املعاملــة علــى محكمــة االســتئناف مبكــة املكرمــة ‪ .‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                      ‫‪1434/6/26‬ه ـ الســاعة ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n\n\n                                                                                     ‫‪184‬‬\n\f      ‫فلــدي أنــا ‪ ...............‬القاضــي باحملكمــة العامــة مبحافظــة جــدة ‪.‬‬\n      ‫يف هــذا اليــوم الثالثــاء املوافــق ‪1434/08/09‬ه ـ كان قــد وردتنــا‬\n      ‫املعاملــة مــن محكمــة االســتئناف بخطابهــم رقــم ‪34194734‬‬\n      ‫وتاريــخ ‪1434/07/24‬ه ـ واملقيــد لدينــا برقــم ‪ 34/194734‬وتاريــخ‬\n      ‫‪1434/07/26‬ه ـ مــن محكمــة االســتئناف مبكــة املكرمــة والتــي‬\n      ‫حتــوي قــرار الدائــرة األحوال الشــخصية األولى رقم ‪ 34271675‬وتاريخ‬\n      ‫‪1434/07/18‬ه ـ جتــاه دعــوى ‪ .............‬ضــد ‪ . .......‬قــد تضمــن القــرار‬\n      ‫(( أنــه بدراســة الصــك وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى‬\n      ‫احلكــم بعــد اإلجــراء األخيــر)) قاضيــا االســتئناف ‪ ............‬ختــم وتوقيــع‬\n      ‫و‪ ............‬ختــم وتوقيــع ولــه وجهــة نظــر رئيــس الدائــرة القاضــي ‪...........‬‬\n      ‫ختــم وتوقيــع ‪ .‬وقــد أمــرت بتهميــش ذلــك علــى ضبطــه وســجله وصلــى‬\n      ‫اهلل علــى نبينــا محمــد والــه وصحبــه وســلم حــرر يف ‪1434/08/09‬ه ـ ‪.‬‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد نحــن قضــاة الدائــرة‬\n      ‫األولــى لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n      ‫يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع‬\n      ‫علــى املعاملــة الــواردة إلينــا شــفع خطــاب فضيلــة رئيــس احملكمــة‬\n      ‫العامــة املســاعد بجــدة رقــم ‪ 34194734‬وتاريــخ ‪1434/7/8‬ه ـ املشــتملة‬\n      ‫علــى الصــك رقــم ‪ 33389019‬وتاريــخ ‪1433/8/21‬ه ـ الصــادر مــن‬\n      ‫فضيلــة الشــيخ ‪ ..........‬القاضــي باحملكمــة العامــة بجــدة املتضمــن‬\n      ‫دعــوى ‪ ...........‬ضــد ‪ ..........‬يف فســخ نــكاح وبدراســة الصــك وصــورة‬\n      ‫ضبطــه تقــرر باألكثريــة املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n‫‪185‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":175,"source_page_end":185,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"36dae0240e9f5f7ce8c76b04197d7a40338f14c211fae1bbfca6ff269c33c67f","normalized_text_hash":"f0d76013334c7f986cddee97b3b8f7d31564c02ed4d8545e39df05b39c275c8d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p175-33389019"},{"id":"d70281a8-80aa-5fe6-9bc3-9a26fd692164","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -هجران -اخلروج من املنزل بسبب الهجران وعدم النفقة -طلب فسخ عقد النكاح بسبب الهجران وعدم النفقة -إيقاف خدمات املدعى عليه -ثبوت الدعوى بشهادة الشهود املعدلن -حكم غيابي بفسخ النكاح بدون عوض بسبب هجران الزوج وعدم نفقته على زوجة.","document_number":"34206957","case_number":"3339702","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بخميس مشيط","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/6","year":"1434","subject":"فسخ نكاح -هجران -اخلروج من املنزل بسبب الهجران وعدم النفقة -طلب فسخ عقد النكاح بسبب الهجران وعدم النفقة -إيقاف خدمات املدعى عليه -ثبوت الدعوى بشهادة الشهود املعدلن -حكم غيابي بفسخ النكاح بدون عوض بسبب هجران الزوج وعدم نفقته على زوجة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/5/6 :‬هـ‬\n               ‫ُ‬                  ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34206957 :‬‬\n                    ‫َر ْق ُم الدعوى‪3339702 :‬‬\n             ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34319517:‬تاريخه‪1434/9/15 :‬هـ‬\n\n\n‫فســخ نــكاح ‪ -‬هجــران ‪ -‬اخلــروج مــن املنــزل بســبب الهجــران وعــدم‬\n‫النفقــة ‪ -‬طلــب فســخ عقــد النــكاح بســبب الهجــران وعــدم النفقــة‬\n‫‪ -‬إيقــاف خدمــات املدعــى عليــه ‪ -‬ثبــوت الدعــوى بشــهادة الشــهود‬\n‫املعدلــن ‪ -‬حكــم غيابــي بفســخ النــكاح بــدون عــوض بســبب هجــران‬\n                                   ‫الــزوج وعــدم نفقتــه علــى زوجــة‪.‬‬\n\n\n\n\n‫‪ -1‬مــا رواه البيهقــي عــن عمــر بــن اخلطــاب رضــي اهلل عنــه أنــه كتــب‬\n‫إلــى أمــراء األجنــاد يف رجــال غابــوا عــن نســائهم فأمرهــم بــأن ينفقــوا أو‬\n‫يطلقــوا فــإن طلقــوا بعثــوا بنفقــه مــا مضــى ( الســن الكبــرى ‪. )469/7‬‬\n‫‪ -2‬قــال ابــن قدامــه يف املغنــي ( فــإذا منعهــا ‪ -‬أي النفقــة ‪ -‬ولــم جتــد مــا‬\n                           ‫تأخــذه واختــارت فراقــه فــرق احلاكــم بينهمــا )‪.‬‬\n                                          ‫‪ -3‬القاعدة الفقهية ‪ :‬رفع الضرر ‪.‬‬\n\n\n\n\n‫حضــرت املدعيــة ولــم يحضــر املدعــى عليه‪،‬لــم يســتطع منــدوب‬\n‫احملكمــة تبليــغ املدعــى عليــه لعــدم تواجــده يف بيتــه وقــد وضــع إعــان‬\n‫احلضــور حتــت بــاب املدعــى عليــه ‪ ،‬مت إيقــاف خدمــات املدعــى عليــه‬\n‫العامــة والبنكيــة عــن طريــق اجلهــات املختصــة‪،‬مت طلــب املدعــى عليــه‬\n\n                                                                                       ‫‪186‬‬\n\f      ‫عــن طريــق إدارة الب ـحـ ــث والتحــري فــورد اجلــواب بأنــه لم ي ـتــوص ـ ــل إليه‬\n      ‫‪ ،‬قــررت احملكمــة الســير يف نظــر الدعــوى ‪ ،‬ادعــت املدعيــة احلاضــرة‬\n      ‫برفقــه والدهــا علــى املدعــى عليــه بأنــه عقــد عليهــا ودخــل بهــا الدخــول‬\n      ‫الشــرعي يف يــوم العقــد وبعــد ســتة أشــهر تقريبــا هجرهــا فخرجــت مــن‬\n      ‫منزلــه بســبب الهجــران وذهبــت إلــى بيــت أهلهــا ‪ ،‬قــررت بأنهــا لهــا‬\n      ‫ســنه ونصــف تقريب ـ ًا وهــي عنــد أهلهــا وطلبــت فســخ نكاحهــا بســبب‬\n      ‫الهجــران وعــدم النفقــة ‪ ،‬أحضــرت شــاهدين مــن اجليــران فشــهدا علــى‬\n      ‫صحــة الدعــوى‪ -‬جــرى تعديــل الشــاهدين ‪ ،‬صــدر احلكــم بفســخ نكاح‬\n      ‫املدعيــة مــن املدعــى عليــه بســبب الهجــران وعــدم النفقــة ‪ ،‬جــرى بعــث‬\n      ‫صــورة مــن الصــك للمحافظــة للبحــث عــن املدعــى عليــه وتســليمه صــوره‬\n      ‫صــك احلكــم ‪ ،‬ورد اجلــواب بأنــه بالبحــث عــن املذكــور لــم يعثــر عليــه‬\n                                      ‫‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).......‬القاضــي يف احملكمــة‬\n      ‫العامــة بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة بخميــس مشــيط برقــم ‪ 3339702‬وتاريــخ‬\n      ‫‪ 1433/01/16‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33100688‬وتاريــخ‬\n      ‫‪ 1433/01/16‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/01/11‬ه ـ افتتحــت‬\n      ‫اجللســة وفيهــا حضــرت (‪ ).......‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪...‬واملعــرف بهــا مــن قبل والدها ‪...‬ســعودي اجلنســية مبوجب الســجل‬\n      ‫املدنــي رقــم (‪ ).......‬ولــم يحضــر املدعــى عليــه وقــد وردتنــا إفــادة محضــر‬\n      ‫اخلصوم بهذه احملكمة (‪ ).......‬برقم ‪ 332280217‬يف ‪1433/12/29‬هـ‬\n‫‪187‬‬\n\f‫املتضمنــة نفيدكــم بأنــه مت الذهــاب الــى منــزل املدعــى عليــه وعنــد‬\n‫مقابلــة أحــد أقربــاء املدعــى عليــه أفادنــا بــأن املدعــى عليــه يســكن‬\n‫بالطابــق الثانــي وال يعلــم إن كان موجــود ًا أو ال وليــس لــه عالقــة بــه‬\n‫وبســؤال املدعيــة عــن دعواهــا أدعــت قائلــة لقــد عقــد علـ ـ ّـي املدعــى عليــه‬\n‫بتاريــخ ‪1432/4/10‬ه ـ بواليــة والــدي علــى مهــر قدره عشــرون ألف ريال‬\n‫اســتلمت منهــا اثنــا عشــر ألــف ريــال ودخــل بــي الدخــول الشــرعي يف يــوم‬\n‫العقــد وقــد هجرنــي مــن تاريــخ ‪1432/10/10‬ه ـ وخرجــت مــن املنــزل‬\n‫بســبب الهجــر يف شــهر ذي احلجــة مــن العــام ‪1432‬ه ـ ومــن ذلــك التاريــخ‬\n‫حتــى اليــوم لــم يســأل عنــي ولــم ينفــق علـ ـ ّـي وقــد تضــررت مــن ذلــك أطلب‬\n‫فســخ نكاحــي منــه هــذه دعــواي ثــم رفعــت اجللســة لطلبــه مــرة أخــرى‬\n‫ويف جلســة أخــرى حضــرت املدعيــة برفقــة املعــرف بهــا والدهــا املدونــة‬\n‫هويتــه ســابق ًا ولــم يحضــر املدعــى عليــه وقــد وردتنــا إفــادة محضــري‬\n‫اخلصــوم بهــذه احملكمــة مــن قبــل املوظــف ‪...‬ونصهــا نفيدكــم بأنــه مت‬\n‫الذهــاب إلــى منــزل املدعــى عليــه مــرات عديــدة يف كل مــرة ال يــرد‬\n‫علينــا أحــد عنــد ذلــك مت وضــع صــورة مــن اخلطــاب مــن خــال البــاب‬\n‫أ ‪.‬ه ـ نصــه وحيــث أن املدعــى عليــه لــه محــل إقامــة معلــوم يف خميــس‬\n‫مشــيط لــذا رفعــت اجللســة لطلــب املدعــى عليــه عــن طريــق الشــرطة ويف‬\n‫جلســة أخــرى حضــرت املدعيــة برفقــة والدهــا املعــرف بهــا وأحضــرت‬\n‫معهــا للشــهادة كال مــن ‪...‬ســعودي بالســجل املدنــي رقــم ‪...‬و‪...‬ســعودي‬\n‫بالســجل املدنــي رقــم ‪...‬وبســؤالهما عمــا لديهمــا مــن شــهادة قــال األول‬\n‫إننــي مــن مواليــد عــام ‪1386‬ه ـ وأســكن يف خميــس مشــيط وأشــهد‬\n‫هلل أن املدعــى عليــه زوج املدعيــة ‪...‬قــد هجــر زوجتــه املدعيــة مــن ســنة‬\n‫وســتة أشــهر وال ينفــق عليهــا علمــا أننــي ووالدهــا زمــاء عمــل وهــم مــن‬\n\n\n                                                                                        ‫‪188‬‬\n\f      ‫جيراننــا وبســؤال الشــاهد الثانــي عمــا لديــه مــن شــهادة فقــال إننــي مــن‬\n      ‫مواليــد ‪1368‬ه ـ وأســكن يف خميــس مشــيط ووالــد املدعيــة جــار لــي‬\n      ‫وأشــهد هلل أن املدعــى عليــه زوج املدعيــة ‪ ...‬قــد هجــر زوجتــه مــن ســنة‬\n      ‫ونصــف تقريبــا وهــي يف هــذه املــدة عنــد والدهــا وهــو الــذي ينفــق عليهــا‬\n      ‫ولــم أر زوجهــا يف املــدة املذكــورة هــذا مــا لــدي كمــا أحضــرت معهــا‬\n      ‫كال مــن ‪ ...‬ســعودي بالســجل املدنــي رقــم ‪...‬و‪ ......‬ســعودي بالســجل‬\n      ‫املدنــي رقــم ‪...‬وبســؤالهما عمــا لديهمــا فقــاال نشــهد هلل بعدالــة الشــهود‬\n                              ‫أعــاه ثــم رفعــت اجللســة حلــن ورود إفــادة الشــرطة‬\n      ‫ويف جلســة أخــرى حضــرت املدعيــة برفقــة املعــرف بهــا والدهــا املدونــة‬\n      ‫هويتــه ســلفا ولــم يحضــر املدعــى عليــه وال مــن ميثلــه وباالطــاع علــى‬\n      ‫أوراق املعاملــة وجــد فيهــا خطــاب قســم اإلحضــار بشــعبة تنفيــذ‬\n      ‫األحــكام احلقوقيــة بشــرطة خميــس مشــيط برقــم ‪602/1/8/3334‬‬\n      ‫يف ‪1433/6/24‬ه ـ املتضمــن أنــه مت إيقــاف خدمــات املدعــو ‪...‬وقــد‬\n      ‫مت البحــث عنــه ولــم يتــم العثــور عليــه أ‪.‬ه ـ مضمونــه وقــد ســبقت منــي‬\n      ‫الكتابة لشعبة التحريات والبحث بخميس مشيط برقم ‪228115/34‬‬\n      ‫يف ‪1434/1/26‬ه ـ فوردتنــي اإلفــادة برقــم ‪ 602/2/2/440‬يف‬\n      ‫‪1434/2/30‬ه ـ املتضمــن بأنــه مت البحــث والتحــري عــن املذكــور ولــم‬\n      ‫يتــم التوصــل إليــه أ‪ .‬ه ـ مضمونــه كمــا متــت مخاطبــة مؤسســة النقــد‬\n      ‫إليقــاف خدماتــه البنكيــة برقــم ‪ 415683/34‬يف ‪1434/2/19‬ه ـ‬\n      ‫فوردتنــا اإلفــادة رقــم ‪ 10716/33‬يف ‪1434/3/1‬ه ـ املتضمنــة أنــه مت‬\n      ‫التعميــم علــى البنــوك واملصــارف العاملــة باململكــة ومت تلقــي اإلجابــة‬\n      ‫املتضمنــة تنفيــذ املطلــوب أ‪.‬ه ـ مضمونــه لــذا فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى ومــا جــاء يف شــهادة الشــهود املعدلــن وباالطــاع علــى اخلطابات‬\n\n\n‫‪189‬‬\n\f‫الــواردة مــن اجلهــات املختصــة واملدونــة أعــاه فقــد ثبــت لــدي هجــر‬\n‫املدعــى عليــه لزوجتــه املدعيــة ســنة وســتة أشــهر ولــم ينفــق عليهــا خــال‬\n‫هــذه املــدة وحكمــت بفســخ نــكاح املدعيــة مــن زوجهــا املدعــى عليــه‬\n‫الغائــب عــن مجلــس احلكــم بــدون عــوض ملــا رواه البيهقــي بســنده عــن‬\n‫عمــر بــن اخلطــاب رضــي اهلل عنــه أنــه كتــب إلــى أمــراء األجنــاد يف‬\n‫رجــال غابــوا عــن نســائهم فأمرهــم بــأن ينفقــوا أو يطلقــوا فــإن طلقــوا‬\n‫بعثــوا بنفقــة مــا مضى(الســن الكبــرى ‪ )469/7‬أ‪.‬ه ـ قــال يف املغنــي ‪( :‬‬\n‫فــإذا منعهــا ‪ -‬أي النفقــة ‪ -‬ولــم جتــد مــا تأخــذه واختــارت فراقــه فــرق‬\n‫احلاكــم بينهمــا ) أ‪.‬ه ـ وكالمــه يف الــزوج احلاضــر غيــر املنفــق ويدخــل‬\n‫مــن بــاب أولــى الــزوج الغائــب غيــر املنفــق وألن مــن قواعــد الشــريعة رفــع‬\n‫ـدء‬\n‫الضــرر واحلــرج وأفهمتهــا بــأن عليهــا العــدة الشــرعية ثــاث حيــض بـ ً‬\n‫مــن تاريــخ اليــوم وأن ال تتــزوج حتــى يكتســب احلكــم القطعيــة ويعتبــر‬\n‫احلكــم غيابيــا يف حكــم املدعــى عليــه وســيتم بعــث نســخة مــن احلكــم‬\n‫للجهــة املختصــة للبحــث عنــه وتبليغــه باحلكــم ومــن ثــم اإلفــادة لنــا عــن‬\n‫ذلــك وقــد قنعــت املدعيــة باحلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/23‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى ســيدنا محمــد وعلــى الــه‬\n‫وصحبــه وســلم ففــي يــوم االثنــن املوافــق‪ 1434/08/15‬ه ـ افتتحــت‬\n‫اجللســة الســاعة وســبق ان بعثنــا خطــاب الــى محافــظ محافظــة خميــس‬\n‫مشــيط برقــم ‪ 341626826‬يف تاريــخ ‪1434/7/5‬ه ـ ـ بخصــوص‬\n‫تكليــف مــن يلــزم بتســليم املدعــى عليــه ‪...‬صــورة صــك احلكــم فوردتنــا‬\n‫االفــادة مــن مديــر مركــز شــرطة اجلنوبيــة برقــم ‪ 4776/2161602‬يف‬\n‫تاريــخ ‪1434/8/7‬هـ ـ املتضمــن انــه بالبحــث عــن املذكــور لــم يعثــر عليه‬\n\n\n                                                                                      ‫‪190‬‬\n\f      ‫لــذا قــررت رفــع املعاملــة إلــى محكمــة االســتئناف لتدقيــق احلكــم‬\n      ‫‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                   ‫وســلم ‪ .‬حــرر يف ‪1434/08/15‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحن قضــاة الدائرة املختصة بتدقيق‬\n      ‫قضايــا األحــوال الشــخصية و األوقــاف والوصايــا والقصــار وبيــوت‬\n      ‫املــال مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة لهــذه‬\n      ‫احملكمــة مــن فضيلــة رئيــس احملكمــة العامــة بخميــس مشــيط رقــم‬\n      ‫‪ 33100688‬وتاريــخ ‪1434/8/16‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة الشــيخ‪ ... /‬برقــم ‪ 34206957‬وتاريــخ ‪1434/5/6‬ه ـ اخلاصــة‬\n      ‫بدعــوى ‪ ...‬ضــد ‪...‬بشــأن نفقــه علــى الصفــة املوضحــة بالصــك املتضمــن‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون بباطنــه وبدراســة الصــك وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪ .‬دائــرة األحــوال الشــخصية‬\n                                       ‫واألوقــاف والوصايــا والقصــار وبيــوت املــال ‪.‬‬\n\n\n\n\n‫‪191‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":186,"source_page_end":191,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"df76cb431a49d6e4bb5aff6298faffc69d08d05908b8506e95bdf02af02ffaaf","normalized_text_hash":"f9010535c26d98708c2f740dd93a7ccc8485a1d0935dec29d71fc4904b4ea76d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p186-34206957"},{"id":"59aed5de-a013-54d5-92bd-ff4d66b2a29f","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول لسوء العشرة -رأت جلنة الصلح الفرقة دون عوض -احلكم بفسخ النكاح دون عوض -احلكم يف حق املدعى عليه حضوري ا.","document_number":"33319506","case_number":"3344473","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/29","year":"1434","subject":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول لسوء العشرة -رأت جلنة الصلح الفرقة دون عوض -احلكم بفسخ النكاح دون عوض -احلكم يف حق املدعى عليه حضوري ا.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/6/29 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33319506 :‬‬\n                    ‫َر ْق ُم الدعوى‪3344473 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34278969‬تاريخه‪1434/7/25:‬هـ‬\n\n\n‫فســخ نــكاح ‪ -‬طلــب الزوجــة فســخ النــكاح بعــد الدخــول لســوء العشــرة‬\n‫‪ -‬رأت جلنــة الصلــح الفرقــة دون عــوض ‪ -‬احلكــم بفســخ النــكاح دون‬\n                       ‫عــوض‪ -‬احلكــم يف حــق املدعــى عليــه حضوري ـ ًا‪.‬‬\n\n\n\n‫‪ .1‬قــول اهلل عــز وجــل ( وإن خفتــم شــقاق بينهمــا فابعثــوا حكمــا مــن‬\n        ‫أهلــه وحكمــا مــن أهلهــا إن يريــدا إصالحــا يوفــق اهلل بينهمــا)‪.‬‬\n‫‪ .2‬قولــه صلــى اهلل عليــه وســلم‪( :‬أميــا امــرأة طلبــت مــن زوجهــا الطــاق‬\n                            ‫مــن غيــر مــا بــأس فحــرام عليهــا رائحــة اجلنــة)‬\n        ‫‪ .3‬قوله صلى اهلل عليه وسلم ( ال ضرر وال ضرار والضرر يزال )‬\n‫‪ .4‬قــال الطبــري يف تفســيره جامــع البيــان مــن تأويــل القــرآن‪:)718/6(:‬‬\n‫( أن علي ـ ًا رضــي اهلل عنــه أتــاه رجــل وامرأتــه ومــع كل واحــد منهمــا‬\n‫فئــام مــن النــاس فأمرهمــا علــي رضــي اهلل عنــه أن يبعثــا حكمــا مــن‬\n‫أهلــه وحكمــا مــن أهلهــا لينظــرا فلــم دنــا منــه احلكمــان قــال لهمــا علــي‬\n‫أتدريــان مــا لكمــا إن رأيتمــا أن تفرقــا فرقتمــا وإن رأيتمــا أن جتمعــا‬\n‫جمعتمــا قــال هشــام قالــت املــرأة رضيــت بكتــاب اهلل لــي وعلــي فقــال‬\n‫الرجــل أمــا الفرقــة فــا فقــال علــي كذبــت واهلل حتــى ترضــى مثــل مــا‬\n                                                                 ‫رضيــت بــه) أ‪.‬ه ـ‬\n‫‪ .5‬قــال ابــن كثيــر رحمــه اهلل تعالــى يف تفســيره ‪( :644/1‬وقــد أجمــع‬\n           ‫جمهــور العلمــاء علــى أن احلكمــن لهمــا اجلمــع والتفرقــة)‪.‬‬\n            ‫‪ .6‬املادة اخلامسة واخلمسون من نظام املرافعات الشرعية ‪.‬‬\n                                                                                      ‫‪192‬‬\n\f      ‫حضــرت املدعيــة املعــرف بهــا مــن قبــل والدهــا‪ ،‬ولــم يحضــر املدعــى‬\n      ‫عليــه وقــد تبلــغ لشــخصه ‪ ،‬ادعــت املدعيــة أن املدعــى عليــه الغائــب عــن‬\n      ‫مجلــس احلكــم تزوجهــا ودخــل بهــا وأجنبــت لــه علــى فــراش الزوجيــة‬\n      ‫ابنـ ًا وبنتـ ًا ‪ ،‬وأنهــا عنــد أهلهــا منــذ مــا يقــارب ثالثــة أشــهر ‪ ،‬وأن املدعــى‬\n      ‫عليــه يســيء عشــرتها‪ ،‬ويضربهــا علــى وجههــا‪ ،‬كمــا أنــه هجرهــا يف‬\n      ‫الفــراش قبــل ذهابهــا ألهلهــا قرابــة ثالثــة أشــهر وأنهــا تضــررت مــن‬\n      ‫بقائهــا يف عصمتــه وتطلــب فســخ نكاحهــا منــه ‪ ،‬جــرى تذكير الزوجة‬\n      ‫بحديــث املصطفــى صلــى اهلل عليــه وســلم‪( :‬أميــا امــرأة طلبــت مــن زوجهــا‬\n      ‫الطــاق مــن غيــر مــا بــأس فحــرام عليهــا رائحــة اجلنــة) فأصــرت علــى‬\n      ‫طلبهــا ‪ ،‬لقــول اهلل تعالــى‪ ( :‬وان خفتــم شــقاق بينهمــا فابعثــوا حكمــا‬\n      ‫مــن أهلــه وحكمــا مــن أهلهــا إن يريــدا إصالحــا يوفــق اهلل بينهمــا)‬\n      ‫اختــارت املــرأة للتحكيــم مــن قبلهــا جلنــة اإلصــاح يف احملكمــة ‪،‬‬\n      ‫حضــر املدعــى عليــه لــدى جلنــة الصلــح ولــم يتوصــل الطرفــان لصلـ ٍـح‬\n      ‫بينهمــا ‪ ،‬رأى حكــم الزوجــة الفرقــة بــدون عــوض ورأى حكــم الــزوج‬\n      ‫الفرقــة بعــوض وقــدره املهــر املســمى بالعقــد ‪ ،‬ورأت اللجنــة الفرقــة‬\n      ‫بــدون عــوض ‪ ،‬ألن قــرار جلنــة الصلــح تضمــن الفرقــة بــدون عــوض ‪،‬‬\n      ‫مت احلكــم بفســخ نــكاح املدعيــة مــن زوجهــا املدعــى عليــه علــى غيــر‬\n      ‫عــوض ‪ ،‬وجــرى إفهــام املدعيــة بــأن عليهــا العــدة الشــرعية لهــذا الفســخ‬\n      ‫اعتبــارا مــن احلكــم ‪ ،‬كمــا جــرى إفهامهــا بــأن ال تتــزوج إال بعــد انتهــاء‬\n      ‫العــدة الشــرعية واكتســاب احلكــم القطيعــة ‪ ،‬يعتبــر هــذا احلكــم يف‬\n      ‫حــق املدعــى عليــه حضوري ـ ًا ‪ ،‬بعــد رفــع احلكــم حملكمــة االســتئناف‬\n                                                                  ‫متــت املصادقــة عليــه ‪.‬‬\n‫‪193‬‬\n\f‫احلمــد هلل وحــده وبعــد لــدي أنــا (‪ ).......‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف برقــم ‪ 3344473‬وتاريــخ ‪ 1433/01/17‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33113796‬وتاريــخ ‪ 1433/01/17‬ه ـ ويف االثنــن‬\n‫‪ 1433/04/05‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 55‬للنظــر يف الدعــوى‬\n‫املرفوعــة مــن (‪ ).......‬ضــد (‪ ).......‬بطلــب فســخ نــكاح وفيهــا حضــرت‬\n‫املدعيــة (‪ ).......‬حتمــل ســجل مدنــي رقــم (‪ ).......‬كمــا حضــر حلضورهــا‬\n‫املعــرف بهــا مــن قبــل والدهــا (‪ ).......‬يحمــل بطاقــة الهويــة الوطنيــة رقــم‬\n‫(‪ ).......‬ولــم يحضــر املدعــى عليــه (‪ ).......‬وقــد وردت إلينــا إفــادة من مدير‬\n‫املدرســة التــي يعمــل بهــا املدعــى عليه برقــم ‪ 33208878‬يف ‪143/2/6‬هـ‬\n‫واملتضمــن (بــأن املدعــى عليــه قد تبلغ بنفســه باملوعد احملــدد) أ‪.‬هـ فعليه‬\n‫وبنــاء علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية فقــد‬\n‫قــررت النظــر يف دعــوى املــرأة املدعيــة يف غيــاب املدعــى عليــه فجــرى‬\n‫ســؤال املدعيــة عــن دعواهــا علــى الغائــب عــن املجلــس الشــرعي ‪........‬‬\n‫فقالــت ادعــي علــى الغائــب عــن املجلــس الشــرعي ‪ ........‬بأنــه زوجــي‬\n‫تزوجنــي بالعقــد الصحيــح ودخــل بــي يف ‪1426/2/23‬ه ـ وأجنبــت لــه‬\n‫علــى فــراش الزوجيــة بنت ـ ًا ‪ .......‬وعمرهــا ســتة ســنوات و‪ .......‬وعمــره‬\n‫ســنتان وثمانيــة أشــهر ولــي مــا يقــارب عنــد أهلــي ثــاث أشــهر مــن تاريــخ‬\n‫‪1433/1/7‬ه ـ واملدعــى عليــه يســيء العشــرة ويقــوم بضربــي علــى وجهي‬\n‫ويف ســنة واحــدة فقــط ضربنــي مــا يقــارب أربــع مــرات أو خمــس مــرات‬\n‫وذلــك بيــده علــى وجهــي ويقــوم بســحبي مــن شــعري وقــد هجرنــي يف‬\n\n\n                                                                                       ‫‪194‬‬\n\f      ‫الفــراش قبــل حضــور ألهلــي مــا يقــارب ثالثــة أشــهر وقــد تضــررت مــن‬\n      ‫بقائــي يف عصمتــه لــذا اطلــب فســخ نكاحــي مــن املدعــى عليــه الغائــب‬\n      ‫عــن املجلــس الشــرعي هــذه دعــواي فجــرى تذكيــر الزوجــة بحديــث‬\n      ‫املصطفــى صلــى اهلل عليــه وســلم ( أميــا امــرأة طلبــت مــن زوجهــا الطــاق‬\n      ‫مــن غيــر مــا بــأس فحــرام عليهــا رائحــة اجلنــة) إال أنهــا أصــرت فعليــه‬\n      ‫ولقــول اهلل تعالــى( وان خفتــم شــقاق بينهمــا فابعثــوا حكمــا مــن أهلــه‬\n      ‫وحكمــا مــن أهلهــا إن يريــدا إصالحــا يوفــق اهلل بينهمــا) فاختــارت‬\n      ‫املــرأة جلنــة اإلصــاح يف احملكمــة فجــرى االتصــال علــى جلنــة اإلصــاح‬\n      ‫لتحديــد موعــد فأفادونــا بأنــه قــد حــدد موعــد يف يوم‪1433/4/24‬ه ـ‬\n      ‫الســاعة التاســعة والنصــف ثــم رفعــت اجللســة وحتــى يــوم األحــد‬\n      ‫‪1433/6/29‬ه ـ الســاعة التاســعة والنصــف وحــرر يف ‪ 1433/04/05‬ه ـ‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم احلمــد هلل وحــده‬\n      ‫وبعــد ويف يــوم األحــد ‪ 1433/06/29‬ه ـ افتتحــت اجللســة يف الســاعة‬\n      ‫‪ 9.55‬وفيهــا حضــرت املدعيــة ‪ .........‬املدونــة هويتهــا ســابقا كما حضر‬\n      ‫حلضورهــا املعــرف بهــا مــن قبــل والدهــا ‪ .........‬املدونــة هويتــه ســابقا ولــم‬\n      ‫يحضــر املدعــى عليــه ‪ ..........‬ولــم يــرد إلينــا مــا يفيــد بتبليغــه وباالطــاع‬\n      ‫علــى املعاملــة وجــدت مــن ضمــن طياتهــا خطــاب مــن مديــر عــام التربيــة‬\n      ‫والتعليــم بالطائــف برقــم ‪ 33754395‬يف ‪1433/4/26‬ه ـ واملتضمــن بأن‬\n      ‫املدعــى عليــه قــد تبلــغ بنفســه باملوعــد احملــدد لــدى جلنــة الصلــح وقــد‬\n      ‫عــادت إلينــا املعاملــة مــن مكتــب الصلــح يف هــذه احملكمــة بالقــرار‬\n      ‫‪ 210‬يف ‪1433/5/22‬ه ـ واملتضمــن مــا نصــه( حضــرت املدعيــة ‪...........‬‬\n      ‫وحضــر حلضورهــا املدعــى عليهــا ‪ ..........‬وبعــرض الصلــح علــى الطرفــن‬\n      ‫فلــم يصطلحــا ثــم حضــر ‪ ...........‬حكمــا عــن الزوجــة كمــا حضــر‬\n\n\n‫‪195‬‬\n\f‫‪ .............‬حكمــا عــن الــزوج وقــرر احلكمــان أســباب اخلــاف ويــرى‬\n‫حكــم الزوجــة الفرقــة بــدون عــوض ويــرى حكــم الــزوج الفرقــة بعــوض‬\n‫وقــدره املهــر املســمى بالعقــد وعليــه تــرى اللجنــة الفرقــة بــدون عــوض‬\n‫وبــاهلل التوفيــق احلكــم ‪ .......‬توقيعــه احلكــم ‪ .......‬توقيعــه أعضــاء جلنــة‬\n‫الصلــح ‪ .....‬توقيعــه ‪ ........‬توقيعــه ‪ ........‬توقيعــه رئيــس قســم اإلصــاح‬\n‫‪ .......‬توقيعــه ) أ‪.‬ه ـ وبعــرض هــذا القــرار علــى املدعيــة قالــت كل ما جاء‬\n‫فيــه صحيــح وأنــا مصــره علــى دعــواي ولســت مســتعدة بالرجــوع إليه ألن‬\n‫املدعــى عليــه غيــر مســتعد بتوفيــر الســكن الشــرعي هكــذا قــررت‬\n‫فجــرى نصحهــا وتخويفهــا بــاهلل عــز وجــل لعلهــا أن ترجــع ويكــون خيــرا‬\n‫لهــا لقــول اهلل تعالــى (وعســى أن تكرهــوا شــيئا وهــو خيــرا لكــم) هــذا‬\n‫كمــا جــرى تذكيرهــا بحديــث املصطفــى صلــى الهــن عليــه وســلم(‬\n‫أميــا امــرأة طلبــت مــن زوجهــا الطــاق مــن غيــر مــا بــأس فحــرام عليهــا‬\n‫رائحــة اجلنــة) إال أنهــا أصــرت فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫ومبــا أن املدعــى عليــه قــد تبلــغ أكثــر مــن مــره ولــم يــرد إلينــا مــا يفيــد‬\n‫عــن ســبب غيابــه وقــد ذكرنــا ملكتــب الصلــح بأنــه قــد حــدد موعــد يف‬\n‫مكتبنــا يف هــذا اليــوم وبنــاء علــى املــادة اخلامســة واخلمســن مــن نظــام‬\n‫املرافعــات الشــرعية ومبــا أن املدعيــة مصــرة علــى دعواهــا ومبــا أن قــرار‬\n‫جلنــة الصلــح قــد تضمــن الفرقــة بــدون عــوض واملــدون آنفــا ولقــول اهلل‬\n‫عــز وجــل ( وان خفتــم شــقاق بينهمــا فابعثــوا حكمــا مــن أهلــه وحكمــا‬\n‫مــن أهلهــا أن يريــدا إصالحــا يوفــق اهلل بينهمــا) وحلديــث املصطفــى‬\n‫صلــى اهلل عليــه وســلم ( ال ضــرر وال ضــرار والضــرر يــزال ) وقــد ذكــر‬\n‫الطبــري يف تفســيره جامــع البيــان مــن تأويــل القــرآن ‪ 718/6‬مــا نصــه (‬\n‫أن علــي رضــي اهلل عنــه اتــاه رجــل وامرأتــه ومــع كل واحــد منهمــا فئــام‬\n\n\n                                                                                          ‫‪196‬‬\n\f      ‫مــن النــاس فأمرهمــا علــي رضــي اهلل عنــه أن يبعثــا حكمــا مــن أهلــه‬\n      ‫وحكمــا مــن أهلهــا لينظــرا فلــم دنــا منــه احلكمــان قــال لهمــا علــي‬\n      ‫اتدريــان مــا لكمــا إن رأيتمــا أن تفرقــا فرقتمــا وان رأيتمــا أن جتمعــا‬\n      ‫جمعتمــا قــال هشــام قالــت املــرأة رضيــت بكتــاب اهلل لــي وعلــي فقــال‬\n      ‫الرجــل أمــا الفرقــة فــا فقــال علــي كذبــت واهلل حتــى ترضــى مثــل‬\n      ‫مــا رضيــت بــه) أ‪.‬ه ـ وذكــر ابــن كثيــر رحمــه اهلل تعالــى يف تفســيره‬\n      ‫‪ 644/1‬مــا نصــه( وقــد أجمــع جمهــور العلمــاء علــى أن احلكمــن لهمــا‬\n      ‫اجلمــع والتفرقــة جلميــع ذلــك فقــد فســخت نــكاح املــرأة املدعيــة ‪........‬‬\n      ‫مــن زوجهــا ‪ .......‬علــى غيــر عــوض وهــذا الفســخ ال رجعــة للمدعــى عليــه‬\n      ‫فيــه حيــث ان زوجتــه قــد بانــت منــه بينونــه صغــرى فــا حتــل لــه إال‬\n      ‫بعقــد جديــد بشــروطه وأركانــه كمــا أفهمــت املــرأة املدعيــة بــأن‬\n      ‫عليهــا العــدة الشــرعية لهــذا الفســخ وهــي ثــاث حيــض اعتبــارا مــن‬\n      ‫تاريــخ ‪1433/6/29‬ه ـ حيــث ذكــرت املدعيــة بــأن دورتهــا مســتمرة‬\n      ‫كمــا أفهمتهــا بــأن ال تتــزوج إال بعــد انتهــاء العــدة الشــرعية واكتســاب‬\n      ‫احلكــم القطيعــة ففهمــت ذلــك وبــه حكمــت وبعرضــه عليهــا قنعــت بــه‬\n      ‫وأفهمتهــا بــأن هــذا احلكــم حكــم حضــوري خاضــع لالســتئناف حســب‬\n      ‫التعليمــات و حــرر يف ‪1433/6/29‬ه ـ وصلــى اهلل علــى نبينــا محمــد‬\n                                                      ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم االثنني املوافق‪ 1434/04/01‬هـ افتتحت‬\n      ‫اجللســة الســاعة العاشــرة والنصــف وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف بالقــرار رقــم ‪ 33425711‬يف ‪1433/10/15‬ه ـ واملتضمــن‬\n      ‫مــا نصــه ( تقــرر اعادتهــا لفضيلــة حاكمهــا ملالحظــة مــا يلــي ‪ -1‬ال‬\n      ‫يوجــد أي تواقيــع علــى مــا جــرى ضبطــه يف هــذه القضيــة حســب الصــورة‬\n\n\n‫‪197‬‬\n\f‫املرفقــة ‪ -2 .‬لــم يرصــد فضيلتــه عقــد النــكاح ولــم يســأل عنــه كمــا‬\n‫لــم يرصــد هويــة املدعــى عليــه ‪ -3 .‬لــم يرصــد فضيلتــه هويــة احلكمــن‬\n‫ولــم يحضــرا لــدى فضيلتــه ولــم يصادقــا علــى األقــوال املنســوبة لهمــا يف‬\n‫الضبــط ‪ -4 .‬اعتمــد قــرار جلنــة اإلصــاح علــى أقــوال الزوجــة وحكمهــا‬\n‫دون أي بينــة ولــم ينظــر أو يناقــض أقــوال الــزوج وحكمــه وقــد جــاء‬\n‫يف قــرار اللجنــة أن الزوجــة وافقــت علــى الرجــوع إلــى زوجهــا إذا قــام‬\n‫بتأثيــث البيــت ولــم يتــم رصــد ذلــك يف ضبــط القضيــة أو مناقشــته أو‬\n‫مينــع رجــوع الزوجــة صلحــا بعــد االجتهــاد يف اإلصــاح بــن الزوجــن‬\n‫وبحضورهمــا مــا امكــن ذلــك كمــا ميكــن للزوجــة إعــادة املهــر إذا‬\n‫متســكت بفســخ النــكاح دون ان تثبــت مــا يكفــي لفســخ النــكاح‬\n‫بغيــر عــوض ‪ -5 .‬علــى فضيلتــه تنبيــه كاتــب الضبــط ملالحظــة قواعــد‬\n‫اللغــة وتصحيحــي مــا حصــل مــن أخطــاء يف صــك احلكــم وضبطــه‬\n‫وكذلــك إثبــات اســم مــن وضــع ختمــه باملصادقــة باســم فضيلــة رئيــس‬\n‫احملكمــة قاضــي اســتئناف ‪ ............‬ختمــه وتوقيعــه قاضــي اســتئناف‬\n‫‪ .................‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ ............‬ختمــه وتوقيعــه فعليــه‬\n‫أجيــب أصحــاب الفضيلــة مســتعينا بــاهلل عــز وجــل وفيهــا حضــرت‬\n‫املدعيــة‪ .................... /‬واملعــرف بهــا والدهــا ‪ ..............‬واملدعــى عليــه‪/‬‬\n‫‪ .................‬واملدونــة هويتهــم ســابقا وقــد عــادت املعاملــة مــن جلنــة الصلــح‬\n‫بالقــرار رقــم ‪/455‬ص يف ‪1433/12/1‬ه ـ واملتضمــن مــا نصــه ( وقــد‬\n‫تعــذر الصلــح وقــد ســعت اللجنــة يف إقنــاع الزوجــة يف الرجــوع لزوجهــا‬\n‫حفاظــا علــى بيتهــا وأبنائهــا وتذكيرهــا بــاهلل ســبحانه وتعالــى فوافقــت‬\n‫للرجــوع لبيــت الزوجيــة علــى أن ترجــع لبيتهــا الســابق وأثاثهــا الســابق‬\n‫إمــا الذهــب فطلبــت اليمــن وقــد أفــاد الــزوج أن الشــقة واألثــاث موجــود‬\n\n\n                                                                                            ‫‪198‬‬\n\f      ‫وزوجتــه األخــرى يف شــقة مســتقلة وقــد ذكــره يف بدايــة اجللســة ثــم‬\n      ‫ناقــض نفســه عندمــا وافقــت الزوجــة بالرجــوع قــال ال أســتطيع تلبيــة‬\n      ‫طلبهــا حيــث أن زوجتــي األخــرى تســكن يف نفــس الشــقة واألثــاث‬\n      ‫وضعتــه يف مخــزن فأقنعنــا الزوجــة بشــقة أخــرى فوافــق أن يبنــي لهــا‬\n      ‫ثــاث غــرف يف ســطح البيــت فوافقــت الزوجــة للرجــوع بعــد ذلــك قــال‬\n      ‫أريــد تأخيــر اجللســة لتفكيــر واالســتخارة فطلبنــا منــه إقــرار بذلــك‬\n      ‫فرفــض كتابــة اإلقــرار ثــم بعــد ذلــك قــال موافــق علــى الشــروط ورجــوع‬\n      ‫الزوجــة ثــم بــدأ يناقــش زوجتــه يف وضــع الرجــوع ثــم غضــب وخــرج‬\n      ‫مــن مجلــس الصلــح وتلفــظ علــى زوجتــه وقــال إنــا غيــر موافــق علــى‬\n      ‫هــذه الشــروط وخــل موضــوع الطــاق ميشــي وقــال لزوجتــه أنتــي زبالــة‬\n      ‫وخــرج مــن مكتــب الصلــح وقــد اتفــق علــى الشــروط اآلتيــة ‪ -1‬اســتعد‬\n      ‫الــزوج أن يبنــي ثــاث غــرف مبنافعهــا وتتــم معاينتهــا مــن هيئــة اخلبــراء‬\n      ‫باحملكمــة ‪ -2.‬اســتعد الــزوج بأثــاث جديــد ‪ -3 .‬اســتعد بعــدم ضــرب‬\n      ‫زوجتــه أو إهانتهــا وهــي كذلــك‪ -4 .‬اتفــق الطرفــان بعــدم دخــول أهــل‬\n      ‫الطرفــن منزلهمــا ‪ -5 .‬اســتعد الــزوج بإيصــال زوجتــه إلــى أهلهــا وقــت‬\n      ‫الزيــارة ‪ -6 .‬اســتعدت الزوجــة أن ال تخــرج مــن منزلهــا إال بــإذن زوجهــا‬\n      ‫‪ -7 .‬اســتعدت الزوجــة أنهــا إذا أخلــت بــأي شــرط مــن الشــروط تتحمــل‬\n      ‫جميــع التكاليــف ‪ -8 .‬اســتعد الــزوج أنــه إذا أخــل بأحــد الشــروط‬\n      ‫يفســخ العقــد ‪ .‬وعليــه فــإن اللجنــة تــرى والــرأي لفضيلتكــم أن الــزوج‬\n      ‫غيــر راغــب يف زوجتــه فتكــون الفرقــة بغيــر عــوض ) أ‪0‬ه ـ وبعــرض‬\n      ‫قــرار هيئــة النظــر علــى املدعيــة قالــت كل مــا جــاء فيــه صحيــح هكــذا‬\n      ‫قــررت وبعــرض ذلــك علــى املدعــى عليــه قــال كل مــا ذكــر يف هــذا‬\n      ‫القــرار صحيــح ســوا أننــي لــم أوافــق علــى الشــرط الــذي ذكــر وهــو أن‬\n\n\n‫‪199‬‬\n\f‫أهلــي ال يحضــرون فهــذا ال يرضــاه أي احــد ولــم أتناقــض وإمنــا قلــت أن‬\n‫زوجتــي قــد كانــت تســكن يف شــقة مســتقلة وأمــا بالنســبة لكلمــة‬\n‫أنتــي زبالــة فليــس بصحيــح والصحيــح أننــي قلــت أســلوبك أســلوب زبالــة‬\n‫حيــث أنهــا اســتثارتني وقالــت لــي ال تلمســني وال تنفــق علــي ولســت‬\n‫برجــل وال عالقــة لــي فيــك ســوى انــك تنفــق علــى أوالدك هكــذا قــرر‬\n‫وبعــرض ذلــك علــى املــرأة املدعيــة قالــت صحيــح أننــي قلت له ال تلمســني‬\n‫وال تنفــق علــي وال عالقــة لــي فيــك ولــم اقــل انــه ليــس برجــل هكــذا‬\n‫قــررت فجــرى ســؤال الــزوج هــل أنــت مســتعد بتأمــن شــقة فقــال نعــم‬\n‫هكــذا قــرر وبعــرض ذلــك علــى املــرأة املدعيــة قالــت لســت مســتعدة‬\n‫بالرجــوع إلــى املدعــى عليــه وذلــك بســبب أســلوبه هكــذا قــررت امــا‬\n‫بالنســبة للملحوظــة االولــى واخلامســة فســوف يجــرى الــازم بــإذن اهلل‬\n‫امــا بالنســبة بالنســبة للملحــوظ الثانيــة فجــرى ســؤال املدعــى عليــه هــل‬\n‫لديــك عقــد النــكاح فقــال ليــس لــدي يف الوقــت احلالــي وهــذه زوجتــي‬\n‫ومهرهــا خمســن الــف ريــال وبعــرض ذلــك علــى املدعيــة قالــت إن املهــر‬\n‫هــو خمســون الــف ريــال امــا بالنســبة للملحوظــة الثالثــة فقــد مت اجــراء‬\n‫ذلــك لــدى القســم باحملكمــة فجــرى نصحهمــا وتذكيرهمــا بــاهلل عــز‬\n‫وجــل وجــرى تذكيــر الزوجــة بحديــث املصطفــى صلــى اهلل عليــه وســلم‬\n‫أميــا امــرأة طلبــت مــن زوجهــا الطــاق مــن غيــر مــا بــأس فحــرام عليهــا‬\n‫رائحــة اجلنــة اال انهــا أصــرت فجــرى تذكيــر الــزوج لعلــه ان يطلقهــا‬\n‫ويعوضــه اهلل خيــر منهــا لقــول اهلل عــز وجــل وعســى أن تكرهــوا شــيئا‬\n‫وهــو خيــر لكــم اال انــه اصــر ولــم اتوصــل الــى نتيجة يف االصــاح بينهما‬\n‫فعليــه ولوصــول القضيــة إلــى هــذا احلــد ولقــرار جلنــة الصلــح واملــدون أنفــا‬\n‫لــذا فاحلكــم علــى حالــة وأمــرت ببعــث املعاملــة إلــى أصحــاب الفضيلــة‬\n\n\n                                                                                        ‫‪200‬‬\n\f      ‫مبحكمــة االســتئناف وصلــى اهلل وســلم علــى ســيدنا محمــد وعلــى الــه‬\n      ‫وصحبــه وســلم حــرر يف ‪1434/4/1‬ه ـ ‪ .‬احلمــد هلل وحــده وبعــد لــدي أنــا‬\n      ‫‪ ..........‬القاضــي باحملكمــة العامــة بالطائــف واخللــف لفضيلــة الشــيخ‬\n      ‫‪ ...........‬ويف هــذا اليــوم االثنــن ‪1434/07/10‬ه ـ افتتحــت اجللســة يف‬\n      ‫متــام الســاعة الثامنــة والربــع صباحــا وفيهــا وردت املعاملــة مــن محكمــة‬\n      ‫االســتئناف برقــم ‪ 331880124‬يف ‪1434/06/21‬ه ـ ومرفــق بهــا قــرار‬\n      ‫دائــرة األحــوال الشــخصية األولــى رقــم ‪ 34240129‬يف ‪1434/06/13‬هـ‬\n      ‫املتضمــن بعــد املقدمــة مــا نصــه ( وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة تقــرر إعادتهــا لفضيلــة القاضــي اخللــف أو القائــم‬\n      ‫بالعمــل إلرفــاق صــورة ضبــط كاملــة مــن واقــع الضبــط تكــون موقعــة‬\n      ‫مــن املدعيــة واملدعــى عليــه ومــن حضــر والكاتــب والقاضــي حيــث‬\n      ‫أن صــورة الضبــط املرفقــة خاليــة مــن توقيعاتهــم وهــو مــا الحظنــاه يف‬\n      ‫الفقــرة أوال مــن قرارنــا رقــم ‪ 33425711‬يف ‪1433/10/15‬ه ـ كمــا‬\n      ‫ينبغــي اســتكمال اجلزئيــة األخيــرة مــن املالحظــة اخلامســة فيمــا يتعلــق‬\n      ‫بوضــع اســم وتوقيــع مــع وضــع ختمــه باســم فضيلــة رئيــس احملكمــة‬\n      ‫مــن مقدمــة الصــك ومــن ثــم إعــادة املعاملــة للتدقيــق واهلل املوفــق قاضــي‬\n      ‫اســتئناف ‪ ..........‬ختمــه وتوقيعــه قاضــي اســتئناف ‪ ...........‬ختمه وتوقيعه‬\n      ‫موافــق علــى املالحظــة ولــي إضافــة رئيــس الدائــرة ‪ .........‬ختمــه وتوقيعــه‬\n      ‫) ا‪.‬ه ـ فعليــه أجيــب اصحــاب الفضيلــة وفقنــي اهلل واياهم أنه مت إكمال‬\n      ‫الــازم نحــو مــا ذكــروه مــن مالحظــات علمــا أن فضيلــة ناظــر الدعــوى‬\n      ‫انتقــل للعمــل باحملكمــة اجلزائيــة بالريــاض وبــاهلل التوفيــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/07/10‬ه ـ‬\n      ‫الســاعة الثامنــة والنصــف صباحــا احلمــد هلل وحــده وبعــد ويف هــذا اليــوم‬\n\n\n‫‪201‬‬\n\f‫األربعــاء ‪1434/08/17‬ه ـ افتتحــت اجللســة يف متــام الســاعة الواحــدة‬\n‫وخمســة عشــر دقيقــة ظهــرا وفيهــا وردت املعاملــة مــن محكمــة‬\n‫االســتئناف مبكــة املكرمــة برقــم ‪ 331880124‬يف ‪1434/08/06‬ه ـ‬\n‫وقــد جــرى تدقيــق احلكــم مــن الدائــرة األولــى لألحــوال الشــخصية‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف وصــدر بشــأنه‬\n‫القــرار رقــم ‪ 34278969‬يف ‪1434/07/25‬ه ـ امل ــدون علــى ظهــر ال ــصك‬\n‫واملتضمــن (احلمــد هلل وح ــده وبعــد فـق ــد اطلعنــا علــى ه ــذا الصــك رق ــم‬\n‫‪ 33319506‬وتاريــخ ‪1433/06/29‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪.......‬‬\n‫واصدرنــا القــرار رقــم ‪ 34278969‬وتاريــخ ‪1434/07/25‬ه ـ املتضمــن‬\n‫املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق عضــو ‪........‬‬\n‫ختمــه وتوقيعــه عضــو ‪ ......‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ ........‬موقــع‬\n‫يف األصــل وموافــق علــى احلكــم ومجــاز) أ‪.‬ه ـ وعليــه فقــد أمــرت بإحلــاق‬\n‫ذلــك بضبطــه وســجله وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/08/17‬ه ـ الســاعة الواحــدة‬\n‫والنصــف ظهــرا‪ .‬احلمــد هلل وحــده والصــاة والســام علــى مــن ال‬\n‫نبــي بعــده ‪ ،‬وبعــد ‪ :‬نحــن قضــاة الدائــرة األولــى لألحــوال الشــخصية‬\n‫واألوقــاف والوصايــا والقصــار وبيــوت املــال يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة‬\n‫إلينــا شــفع خطــاب فضيلــة رئيــس احملكمــة العامــة بالطائــف املكلــف‬\n‫رقــم ‪ 331880124‬وتاريــخ ‪1434/7/15‬ه ـ املشــتملة علــى الصــك رقــم‬\n‫‪ 33319506‬وتاريــخ ‪1433/6/29‬ه ـ الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة العامــة بالطائــف الشــيخ (‪ )..........‬املتضمــن دعــوى ‪........‬‬\n‫ضــد ‪ .......‬يف فســخ نــكاح وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n\n\n                                                                                     ‫‪202‬‬\n\f      ‫االعتراضيــة تقــرر املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ ،‬واهلل‬\n           ‫املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪203‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":192,"source_page_end":203,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7e60ae6b60074b49ea4bb6d0a0e2df786c0b768c27df22